window.QUIZ_DATA = {"mcq":[{"id":"m1","n":1,"ch":"c1","page":"c1","q":"彩色圖片由 R、G、B 三個 channel 組成，每個 pixel 值的範圍為何？","o":["0～1","0～255","−1～1","0～1023"],"a":1,"e":"每個像素值介於 0～255。"},{"id":"m2","n":2,"ch":"c1","page":"c1","q":"一張 224×224 的 RGB 圖片共有幾個數值？","o":["50,176","672","150,528","224"],"a":2,"e":"224 × 224 × 3 = 150,528。"},{"id":"m3","n":3,"ch":"c1","page":"c1","q":"AI、Machine Learning 與 Deep Learning 三者的關係為何？","o":["DL ⊃ ML ⊃ AI","ML ⊃ AI ⊃ DL","三者互相獨立","AI ⊃ ML ⊃ DL"],"a":3,"e":"三層同心圓，DL 是 ML 的子集，ML 是 AI 的子集。"},{"id":"m4","n":4,"ch":"c1","page":"c1","q":"Machine Learning 與 Deep Learning 的主要差異是什麼？","o":["ML 由人工擷取特徵，DL 由模型自動學習特徵","ML 不需要資料","DL 不需要訓練","ML 只能處理影像"],"a":0,"e":"ML 是「輸入 → 人工擷取特徵 → 分類」，DL 由同一個神經網路同時做特徵擷取和分類。"},{"id":"m5","n":5,"ch":"c1","page":"c1","q":"下列何者是 Deep Learning 的特性？","o":["少量資料就能訓練好","可解釋性比傳統 ML 高","必須人工設計特徵","通常需要大量資料與 GPU"],"a":3,"e":"DL 需要大量資料、運算資源大，可解釋性較差（像黑盒子）。"},{"id":"m6","n":6,"ch":"c1","page":"c1","q":"Supervised Learning 的輸入資料是什麼？","o":["沒有標籤的資料","狀態與動作","有標籤的資料","只有獎勵"],"a":2,"e":"監督式學習用有標籤的資料，和正確答案比較算出誤差來修正。"},{"id":"m7","n":7,"ch":"c1","page":"c1","q":"PCA 屬於哪一種學習方式？","o":["非監督式","監督式","強化學習","以上皆非"],"a":0,"e":"PCA 不需要標籤，是找資料結構的降維方法。"},{"id":"m8","n":8,"ch":"c1","page":"c1","q":"Reinforcement Learning 如何得到回饋？","o":["依結果給獎勵（Reward）","和正確答案比較","沒有任何回饋","人工逐筆標註"],"a":0,"e":"強化學習不給正確答案，只依結果評估給獎勵。"},{"id":"m9","n":9,"ch":"c1","page":"c1","q":"SVM 的主要目標為何？","o":["找最佳超平面並最大化間隔","找變異最大的方向","找最近的 K 個鄰居","最小化 MAE"],"a":0,"e":"SVM 找最佳超平面（hyperplane）區分類別，同時最大化間隔（margin）。"},{"id":"m10","n":10,"ch":"c1","page":"c1","q":"資料無法用一條直線分開時，SVM 會使用什麼方法？","o":["刪掉離群值","降到一維","增加 K 值","用 Kernel Trick 投影到更高維空間"],"a":3,"e":"核技巧把資料投影到更高維，讓原本線性不可分的資料變得可分。"},{"id":"m11","n":11,"ch":"c1","page":"c1","q":"SVM 的主要缺點為何？","o":["預測時要和所有訓練樣本算距離","只能處理沒有標籤的資料","無法使用 Kernel Trick","大資料集計算最佳超平面非常耗時"],"a":3,"e":"另外 kernel 難選、多分類較複雜；「預測時要和所有樣本算距離」是 KNN 的缺點。"},{"id":"m12","n":12,"ch":"c1","page":"c1","q":"KNN 的 K 為什麼通常設為奇數？","o":["避免投票平手","計算比較快","減少記憶體","提高維度"],"a":0,"e":"K 為偶數時可能票數各半。"},{"id":"m13","n":13,"ch":"c1","page":"c1","q":"KNN 的主要缺點為何？","o":["預測時要和所有樣本算距離，資料越大越慢","只能做二元分類","訓練時間很長","一定要用 GPU"],"a":0,"e":"KNN 不需要訓練，但預測很慢；另外高維時距離失去意義、無法處理非線性。"},{"id":"m14","n":14,"ch":"c1","page":"c1","q":"Minkowski Distance 中 p=1 時是哪一種距離？","o":["歐幾里得距離","切比雪夫距離","餘弦距離","曼哈頓距離"],"a":3,"e":"p = 1 是曼哈頓距離（L1），p = 2 是歐幾里得距離（L2）。"},{"id":"m15","n":15,"ch":"c1","page":"c1","q":"給定 A(0, 0)、B(3, 4)，請計算兩點的 Euclidean Distance。","o":["7","25","12","5"],"a":3,"e":"√(3² + 4²) = √25 = 5。"},{"id":"m16","n":16,"ch":"c1","page":"c1","q":"給定 A(0, 0)、B(3, 4)，請計算兩點的 Manhattan Distance。","o":["5","12","7","25"],"a":2,"e":"|3| + |4| = 7。"},{"id":"m17","n":17,"ch":"c1","page":"c1","q":"處理高維度資料時，哪一種距離比較穩健？","o":["曼哈頓距離","歐幾里得距離","兩者一樣","都不能用"],"a":0,"e":"歐幾里得的平方會放大少數差異大的維度；曼哈頓每一維算得一樣重。"},{"id":"m18","n":18,"ch":"c1","page":"c1","q":"PCA 的 Principal Component 是什麼方向？","o":["誤差最小的方向","資料變異性最大的方向","類別的分界方向","隨機的方向"],"a":1,"e":"PCA 把資料投影到變異最大的方向，以較少維度保留主要資訊。"},{"id":"m19","n":19,"ch":"c1","page":"c1","q":"PCA 的主要缺點為何？","o":["需要標籤","只能處理彩色圖","會增加維度","是線性方法，對非線性資料有限，且會遺失細節"],"a":3,"e":"PCA 是線性降維，只保留變異最大的方向，可能損失重要細節。"},{"id":"m20","n":20,"ch":"c1","page":"c1","q":"Activation Function 的主要目的為何？","o":["加快訓練","減少參數","標準化輸入","引入非線性"],"a":3,"e":"講義寫「Introduce non-linearity」。"},{"id":"m21","n":21,"ch":"c1","page":"c1","q":"為什麼神經網路需要 Activation Function？","o":["疊再多層也只等於一層線性模型","準確率一定更高","參數變成 0","無法前向傳播"],"a":0,"e":"線性函數疊線性函數還是線性，學不出彎曲的決策邊界。"},{"id":"m22","n":22,"ch":"c1","page":"c1","q":"ReLU 的輸入為 −2 時，輸出為何？","o":["−2","−0.2","0","2"],"a":2,"e":"ReLU = max(0, x)，負數變 0。"},{"id":"m23","n":23,"ch":"c1","page":"c1","q":"Leaky ReLU 定義為 max(0.1x, x)，輸入為 −2 時，輸出為何？","o":["0","0.2","−2","−0.2"],"a":3,"e":"max(−0.2, −2) = −0.2，負數區保留 0.1 的斜率。"},{"id":"m24","n":24,"ch":"c1","page":"c1","q":"Sigmoid 的輸入為 0 時，輸出為何？","o":["0","1","−1","0.5"],"a":3,"e":"1 / (1 + e⁰) = 1/2。Sigmoid 輸出範圍 0～1。"},{"id":"m25","n":25,"ch":"c1","page":"c1","q":"多類別分類的輸出層通常使用哪一個函數？","o":["Softmax","ReLU","tanh","不需要激活函數"],"a":0,"e":"Softmax 把各類別分數轉成加總為 1 的機率分布；二元分類用 Sigmoid。"},{"id":"m26","n":26,"ch":"c1","page":"c1","q":"要判斷一張圖片是貓、狗或鳥，輸出層與 Loss Function 應該如何搭配？","o":["Sigmoid ＋ MSE","Softmax ＋ MAE","Softmax ＋ Cross-Entropy","ReLU ＋ Cross-Entropy"],"a":2,"e":"多類別用 Softmax，分類任務用交叉熵。"},{"id":"m27","n":27,"ch":"c1","page":"c1","q":"迴歸任務常用的 Loss Function 為何？","o":["Cross-Entropy","Accuracy","Softmax","MSE 或 MAE"],"a":3,"e":"分類用交叉熵，迴歸用均方誤差（MSE）或平均絕對誤差（MAE）。"},{"id":"m28","n":28,"ch":"c1","page":"c1","q":"給定真實值 (3, 5)、預測值 (2, 7)，請計算 MAE。","o":["1.5","2.5","3","5"],"a":0,"e":"(|1| + |−2|) ÷ 2 = 1.5。"},{"id":"m29","n":29,"ch":"c1","page":"c1","q":"給定真實值 (3, 5)、預測值 (2, 7)，請計算 MSE。","o":["1.5","3","5","2.5"],"a":3,"e":"(1² + 2²) ÷ 2 = 2.5。"},{"id":"m30","n":30,"ch":"c1","page":"c1","q":"Cross-Entropy 有什麼特性？","o":["模型給正確答案的機率越高，損失越大","和正確答案無關","模型給正確答案的機率越低，損失越大","永遠等於 0"],"a":2,"e":"交叉熵只看 −log(正確答案的機率)，機率 1 → 損失 0，機率趨近 0 → 損失趨近無限大。"},{"id":"m31","n":31,"ch":"c1","page":"c1","q":"Backward Propagation 是用什麼方法計算每個權重的梯度？","o":["畢氏定理","大數法則","貝氏定理","連鎖律（Chain Rule）"],"a":3,"e":"從輸出端一路把每一層的導數乘回來。"},{"id":"m32","n":32,"ch":"c1","page":"c1","q":"Sigmoid 的斜率最大只有 0.25，深層網路使用 Sigmoid 容易發生什麼問題？","o":["梯度爆炸","過擬合","梯度消失","資料不足"],"a":2,"e":"越前面的層要乘越多個小於 1 的斜率，梯度趨近 0。"},{"id":"m33","n":33,"ch":"c1","page":"c1","q":"給定 w=2、梯度=4、learning rate=0.1，請計算梯度下降更新後的 w。","o":["1.6","2.4","−2","1.96"],"a":0,"e":"w_new = 2 − 0.1 × 4 = 1.6。"},{"id":"m34","n":34,"ch":"c1","page":"c1","q":"Learning Rate 設得太大會發生什麼問題？","o":["收斂變慢","沒有影響","參數變少","來回震盪、跳過最佳解，甚至發散"],"a":3,"e":"學習率太小則是收斂太慢。"},{"id":"m35","n":35,"ch":"c1","page":"c1","q":"Learning Rate 屬於參數還是超參數？","o":["模型學出來的參數","評估指標","損失函數","需要人設定的超參數"],"a":3,"e":"學習率由人設定，不會被模型學習。"},{"id":"m36","n":36,"ch":"c1","page":"c1","q":"Adam Optimizer 結合了哪兩種方法？","o":["SGD 與 Momentum","RMSProp 與 SGD","Momentum 與 RMSProp","PCA 與 SGD"],"a":2,"e":"Momentum 決定方向，RMSProp 決定步伐大小。"},{"id":"m37","n":37,"ch":"c1","page":"c1","q":"RMSProp 遇到梯度很大的參數時，會如何調整 learning rate？","o":["降低該參數的學習率","提高該參數的學習率","停止更新","把梯度設為 0"],"a":0,"e":"梯度大就走小步，避免跳過最佳解；梯度小則相對加大學習率。"},{"id":"m38","n":38,"ch":"c1","page":"c1","q":"Momentum 的主要作用為何？","o":["減少參數","有慣性，在平坦處或局部最小值仍能繼續前進","不需要學習率","保證找到全域最小值"],"a":1,"e":"實際移動 ＝ 負梯度 ＋ 上一步的移動，有機會衝過小山丘。"},{"id":"m39","n":39,"ch":"c1","page":"c1","q":"每次更新權重只用一筆資料計算梯度的方法是什麼？","o":["Batch GD","Mini-batch GD","Adam","SGD"],"a":3,"e":"SGD 一次看一張；Batch GD 一次看全部；Mini-batch 一次看一小批（最常用）。"},{"id":"m40","n":40,"ch":"c1","page":"c1","q":"Label Encoding（Apple=1、Chicken=2、Broccoli=3）的主要問題是什麼？","o":["維度爆炸","虛假的大小順序","無法表示類別","只能二元分類"],"a":1,"e":"模型可能誤以為 Broccoli &gt; Chicken &gt; Apple；維度爆炸是 One-Hot 的問題。"},{"id":"m41","n":41,"ch":"c2","page":"c2","q":"Convolution 運算在做什麼？","o":["把整張圖取平均","把負數變 0","把圖片展平成一維","濾波器在圖上滑動，對應位置相乘後相加"],"a":3,"e":"每個位置算一次加權總和，得到特徵圖的一個值。"},{"id":"m42","n":42,"ch":"c2","page":"c2","q":"卷積層 Filter 的權重屬於什麼？","o":["超參數","評估指標","可學習的參數","固定不變的常數"],"a":2,"e":"filter 的權重與 bias 由反向傳播學出來。"},{"id":"m43","n":43,"ch":"c2","page":"c2","q":"給定輸入 5×5，使用 3×3 的 Filter，stride=1，padding=0，輸出 Feature Map 的大小為何？","o":["3×3","5×5","2×2","7×7"],"a":0,"e":"5 − 3 + 1 = 3。"},{"id":"m44","n":44,"ch":"c2","page":"c2","q":"給定輸入影像大小為 28×28，使用 5×5 的 Filter，stride=1，padding=0，輸出 Feature Map 的大小為何？","o":["23×23","28×28","26×26","24×24"],"a":3,"e":"(28 + 0 − 5) / 1 + 1 = 24。"},{"id":"m45","n":45,"ch":"c2","page":"c2","q":"給定輸入 32×32，使用 3×3 的 Filter，stride=1，padding=1，輸出 Feature Map 的大小為何？","o":["30×30","16×16","34×34","32×32"],"a":3,"e":"(32 + 2 − 3) / 1 + 1 = 32，same padding。"},{"id":"m46","n":46,"ch":"c2","page":"c2","q":"給定輸入 5×5，使用 3×3 的 Filter，stride=2，padding=0，輸出 Feature Map 的大小為何？","o":["2×2","3×3","1×1","4×4"],"a":0,"e":"⌊(5 − 3) / 2⌋ + 1 = 2。"},{"id":"m47","n":47,"ch":"c2","page":"c2","q":"計算輸出 Feature Map 大小的公式為何？","o":["m = n × f","m = (n − f) × s","m = n + p − s","m = ⌊(n + 2p − f) / s⌋ + 1"],"a":3,"e":"n 輸入邊長、f 濾波器邊長、p padding、s stride。"},{"id":"m48","n":48,"ch":"c2","page":"c2","q":"卷積層輸出 Feature Map 的深度由什麼決定？","o":["輸入的頻道數","濾波器的數量","stride","padding"],"a":1,"e":"用幾個濾波器，輸出就有幾張特徵圖。"},{"id":"m49","n":49,"ch":"c2","page":"c2","q":"輸入為 5×5×3 的彩色圖片時，Filter 的深度必須是多少？","o":["3","1","5","任意"],"a":0,"e":"濾波器頻道數必須等於輸入頻道數。"},{"id":"m50","n":50,"ch":"c2","page":"c2","q":"Padding 是在輸入圖片外圍補什麼？","o":["1","255","0","平均值"],"a":2,"e":"例如 5×5 補一圈 0 變成 7×7。"},{"id":"m51","n":51,"ch":"c2","page":"c2","q":"為什麼需要使用 Padding？","o":["增加可訓練參數","把負數變 0","減少濾波器數量","避免特徵圖越卷越小，並增加角落像素的貢獻"],"a":3,"e":"這是模擬考第 1 題的兩個重點。"},{"id":"m52","n":52,"ch":"c2","page":"c2","q":"給定輸入 5×5、3×3 的 Filter、stride=1、沒有 padding，角落的 pixel 會被卷積到幾次？","o":["1 次","3 次","9 次","4 次"],"a":0,"e":"角落只被卷到一次，中間像素被卷好幾次，所以邊緣資訊容易被忽略。"},{"id":"m53","n":53,"ch":"c2","page":"c2","q":"使用 3×3 的 Filter、stride=1，padding 要設多少才能讓輸出與輸入同尺寸？","o":["0","3","2","1"],"a":3,"e":"(n + 2 − 3) + 1 = n。"},{"id":"m54","n":54,"ch":"c2","page":"c2","q":"其他條件不變，stride 變大時，輸出 Feature Map 會如何變化？","o":["變大","不變","變小","深度變大"],"a":2,"e":"每次跳越多格，能停的位置越少。"},{"id":"m55","n":55,"ch":"c2","page":"c2","q":"ReLU 的定義為何？","o":["1 / (1 + e⁻ˣ)","max(0, x)","tanh(x)","|x|"],"a":1,"e":"負數轉為 0，正數保留。"},{"id":"m56","n":56,"ch":"c2","page":"c2","q":"ReLU 的優點為何？","o":["輸出一定在 0～1 之間","不會有神經元停止學習的問題","只要比大小、計算快，正值區梯度固定為 1","有可訓練參數"],"a":2,"e":"(B) 錯，ReLU 會有 Dying ReLU。"},{"id":"m57","n":57,"ch":"c2","page":"c2","q":"何謂 Dying ReLU？","o":["神經元持續輸出負值，梯度為 0 而永久停止學習","梯度太大導致發散","ReLU 輸出永遠為 1","ReLU 讓參數變多"],"a":0,"e":"負數區斜率為 0，梯度傳不回去。"},{"id":"m58","n":58,"ch":"c2","page":"c2","q":"哪一種 Activation Function 可以改善 Dying ReLU？","o":["Sigmoid","Softmax","Flatten","Leaky ReLU 或 ELU"],"a":3,"e":"負數區仍保留一點斜率，梯度還能流動。"},{"id":"m59","n":59,"ch":"c2","page":"c2","q":"Pooling 的主要目的為何？","o":["增加特徵圖尺寸","縮小特徵圖，在不丟失重要資訊下減少計算量與參數","增加頻道數","引入非線性"],"a":1,"e":"模擬考第 2 題；另外也讓模型不受微小位移影響。"},{"id":"m60","n":60,"ch":"c2","page":"c2","q":"給定 2×2 區塊 [[4, 123], [56, 99]]，Max Pooling 的結果為何？","o":["123","70.5","4","282"],"a":0,"e":"取最大值。"},{"id":"m61","n":61,"ch":"c2","page":"c2","q":"給定 2×2 區塊 [[1, 3], [5, 7]]，Average Pooling 的結果為何？","o":["7","16","1","4"],"a":3,"e":"(1 + 3 + 5 + 7) ÷ 4 = 4。"},{"id":"m62","n":62,"ch":"c2","page":"c2","q":"24×24×64 的 Feature Map 經過 2×2、stride=2 的 Max Pooling，輸出大小為何？","o":["24×24×32","12×12×32","12×12×128","12×12×64"],"a":3,"e":"高寬減半，深度不變。"},{"id":"m63","n":63,"ch":"c2","page":"c2","q":"一層 2×2 的 Max Pooling 有幾個可訓練參數？","o":["4","0","1","5"],"a":1,"e":"Pooling 只是固定的運算，沒有權重。"},{"id":"m64","n":64,"ch":"c2","page":"c2","q":"Pooling 會保持 Feature Map 的哪一項不變？","o":["高","寬","深度（頻道數）","數值總數"],"a":2,"e":"Pooling 對每個頻道分開做。"},{"id":"m65","n":65,"ch":"c2","page":"c2","q":"Pooling 的 stride 設得太大，可能造成什麼問題？","o":["參數暴增","丟失重要資訊","梯度爆炸","頻道數增加"],"a":1,"e":"講義提醒 stride 太大會丟失重要資訊。"},{"id":"m66","n":66,"ch":"c2","page":"c2","q":"下列哪一層有可訓練的參數？","o":["ReLU","Max Pooling","Flatten","全連接層"],"a":3,"e":"ReLU、Max Pool、Flatten 都沒有參數。"},{"id":"m67","n":67,"ch":"c2","page":"c2","q":"12×12×64 的 Feature Map 經過 Flatten 之後，長度為何？","o":["9,216","768","144","4,096"],"a":0,"e":"12 × 12 × 64 = 9,216。"},{"id":"m68","n":68,"ch":"c2","page":"c2","q":"在 CNN 的架構中，Fully Connected Layer 扮演什麼角色？","o":["縮小特徵圖","偵測邊緣","整合卷積與池化抽出的特徵，完成分類","補 0"],"a":2,"e":"模擬考第 8 題；進 FC 前要先 Flatten。"},{"id":"m69","n":69,"ch":"c2","page":"c2","q":"10 類分類的 CNN，最後一層 Fully Connected Layer 的節點數應該是多少？","o":["128","10","1","和輸入大小相同"],"a":1,"e":"最後一層節點數 ＝ 類別數，再接 Softmax。"},{"id":"m70","n":70,"ch":"c2","page":"c2","q":"講義 MNIST 的 CNN 中，哪一部分的參數最多？","o":["Conv_1","Conv_2","Max Pooling","全連接層（約 98%）"],"a":3,"e":"FC(128) 有 1,179,776 個參數，佔 1,199,882 的約 98%。"},{"id":"m71","n":71,"ch":"c2","page":"c2","q":"給定輸入 28×28×1，使用 32 個 3×3 的 Filter，請計算卷積層的參數量。","o":["288","320","9,248","21,632"],"a":1,"e":"(3 × 3 × 1 + 1) × 32 = 320。"},{"id":"m72","n":72,"ch":"c2","page":"c2","q":"給定 RGB 輸入，使用 16 個 3×3 的 Filter，請計算卷積層的參數量。","o":["160","144","448","432"],"a":2,"e":"(3 × 3 × 3 + 1) × 16 = 28 × 16 = 448。"},{"id":"m73","n":73,"ch":"c2","page":"c2","q":"給定輸入深度 32，使用 64 個 3×3 的 Filter，請計算卷積層的參數量。","o":["18,496","18,432","640","576"],"a":0,"e":"(3 × 3 × 32 + 1) × 64 = 289 × 64 = 18,496。"},{"id":"m74","n":74,"ch":"c2","page":"c2","q":"給定輸入 128 維、輸出 10 類的 Fully Connected Layer，請計算參數量。","o":["1,280","138","1,290","1,300"],"a":2,"e":"(128 + 1) × 10 = 1,290。"},{"id":"m75","n":75,"ch":"c2","page":"c2","q":"每個 Filter 有幾個 bias？","o":["每個權重一個","每個頻道一個","0 個","1 個"],"a":3,"e":"每個濾波器只有一個純量 bias。"},{"id":"m76","n":76,"ch":"c2","page":"c2","q":"下列何者是參數（parameter）？","o":["學習率","濾波器的權重","stride","batch size"],"a":1,"e":"參數由模型在訓練中學出來；其他三個是訓練前人設定的。"},{"id":"m77","n":77,"ch":"c2","page":"c2","q":"下列何者是超參數（hyperparameter）？","o":["濾波器的權重","全連接層的 bias","BN 的 γ","stride"],"a":3,"e":"stride 是訓練前設定的；γ 是 BN 的可學習參數。"},{"id":"m78","n":78,"ch":"c2","page":"c2","q":"模型的參數（parameter）是如何更新的？","o":["人工手動調整","梯度下降與反向傳播","Validation 結果","資料擴增"],"a":1,"e":"超參數才是看 Validation 結果手動調整。"},{"id":"m79","n":79,"ch":"c2","page":"c2","q":"小的 Filter（例如 3×3）擅長捕捉什麼特徵？","o":["細節，例如邊緣、紋理","整張圖的大範圍形狀","顏色平均","類別機率"],"a":0,"e":"大濾波器擅長捕捉較大範圍的特徵。"},{"id":"m80","n":80,"ch":"c2","page":"c2","q":"兩層 3×3 卷積疊起來的感受野，等於一層多大的卷積？","o":["3×3","6×6","9×9","5×5"],"a":3,"e":"三層 3×3 則等於 7×7。"},{"id":"m81","n":81,"ch":"c2","page":"c2","q":"為什麼常用兩層 3×3 卷積取代一層 5×5 卷積？","o":["感受野比 5×5 大","感受野相同，但參數較少（18 對 25），還多一次非線性","不需要 padding","輸出尺寸一定比較大"],"a":1,"e":"VGG 全部用 3×3 就是這個原因。"},{"id":"m82","n":82,"ch":"c2","page":"c2","q":"何謂 CNN 的參數共享（Parameter Sharing）？","o":["不同層共用同一組 bias","同一個濾波器在整張圖的不同位置重複使用","所有濾波器的權重都一樣","訓練集和測試集共用參數"],"a":1,"e":"所以參數量和輸入圖片大小無關。"},{"id":"m83","n":83,"ch":"c2","page":"c2","q":"何謂 CNN 的連接稀疏性（Sparsity of Connections）？","o":["很多權重是 0","只有一半的節點會被訓練","層與層之間沒有連接","每個輸出只由輸入的一小塊區域算出來"],"a":3,"e":"不像全連接層要連到每一個像素。"},{"id":"m84","n":84,"ch":"c2","page":"c2","q":"何謂 CNN 的不變性（Invariance）？","o":["特徵不論出現在圖片哪個位置都偵測得到","參數在訓練過程中永遠不變","輸出尺寸一定等於輸入尺寸","不受 learning rate 影響"],"a":0,"e":"模擬考第 10 題的關鍵字之一，另外兩個是參數共享、連接稀疏性。"},{"id":"m85","n":85,"ch":"c2","page":"c2","q":"28×28 灰階圖用全連接層產生與 Conv_1 一樣多的節點需要約 1,696 萬個參數，CNN 的 Conv_1 只需要 320 個，主要原因為何？","o":["CNN 用了 Dropout","參數共享與連接稀疏性","CNN 用了 Softmax","CNN 沒有 bias"],"a":1,"e":"模擬考第 10 題的關鍵字。"},{"id":"m86","n":86,"ch":"c3","page":"c3","q":"在訓練模型時，哪一個資料集是用來更新權重的？","o":["Training set","Validation set","Test set","三者都會"],"a":0,"e":"Validation 和 Test 都不更新權重。"},{"id":"m87","n":87,"ch":"c3","page":"c3","q":"在訓練模型時，Validation set 扮演什麼角色？","o":["更新權重","調整超參數、挑選最佳模型、判斷 overfitting 或 Early Stopping","只在最後用一次","做資料擴增"],"a":1,"e":"模擬考第 9 題。"},{"id":"m88","n":88,"ch":"c3","page":"c3","q":"在訓練模型時，Test set 扮演什麼角色？","o":["每個 epoch 都用來更新權重","用來調整學習率","訓練全部結束後只用一次，評估最終的泛化能力","和 Validation set 完全相同"],"a":2,"e":"拿 Test 來調模型會讓評估結果過度樂觀。"},{"id":"m89","n":89,"ch":"c3","page":"c3","q":"Confusion Matrix 對角線上的格子代表什麼？","o":["預測錯誤的數量","預測正確的數量","類別的總數","模型的參數"],"a":1,"e":"非對角線是預測錯誤，可看出「誰被誤認成誰」。"},{"id":"m90","n":90,"ch":"c3","page":"c3","q":"給定 TP=90、FN=10、FP=5、TN=40，請計算 Accuracy。","o":["0.9","0.947","0.889","0.897"],"a":3,"e":"(90 + 40) ÷ 145 ≈ 0.897。"},{"id":"m91","n":91,"ch":"c3","page":"c3","q":"給定 TP=90、FN=10、FP=5、TN=40，請計算 Precision。","o":["0.947","0.9","0.897","0.111"],"a":0,"e":"TP ÷ (TP + FP) = 90 ÷ 95 ≈ 0.947。"},{"id":"m92","n":92,"ch":"c3","page":"c3","q":"給定 TP=90、FN=10、FP=5、TN=40，請計算 Recall。","o":["0.947","0.889","0.9","0.897"],"a":2,"e":"TP ÷ (TP + FN) = 90 ÷ 100 = 0.9。"},{"id":"m93","n":93,"ch":"c3","page":"c3","q":"Recall 和哪一個指標相同？","o":["Precision","Specificity","FPR","Sensitivity（TPR）"],"a":3,"e":"Recall ＝ Sensitivity ＝ TPR；Specificity ＝ TNR。"},{"id":"m94","n":94,"ch":"c3","page":"c3","q":"Precision 的分母是什麼？","o":["實際為正的數量","預測為正的數量","全部樣本數","實際為負的數量"],"a":1,"e":"Recall 的分母才是實際為正的數量。"},{"id":"m95","n":95,"ch":"c3","page":"c3","q":"疾病篩檢通常最重視哪一個指標？","o":["Precision","Specificity","Accuracy","Recall"],"a":3,"e":"寧可多抽幾個複檢，也不要漏掉真的病人。"},{"id":"m96","n":96,"ch":"c3","page":"c3","q":"F1 是 Precision 與 Recall 的什麼平均？","o":["算術平均","乘積","調和平均","最大值"],"a":2,"e":"任一個很低，F1 就會很低。"},{"id":"m97","n":97,"ch":"c3","page":"c3","q":"100 人中只有 5 人有病，模型全部預測「沒病」，Accuracy 與 Recall 分別為何？","o":["Accuracy 95%，但 Recall 是 0","Accuracy 5%","Recall 是 1","Precision 是 1"],"a":0,"e":"類別不平衡時 Accuracy 會失真，要搭配 Precision、Recall 看。"},{"id":"m98","n":98,"ch":"c3","page":"c3","q":"何謂 Overfitting？","o":["訓練與測試表現都很差","訓練表現好，但在沒看過的資料上表現差","訓練表現差，測試表現好","訓練速度太慢"],"a":1,"e":"像只會背考古題。"},{"id":"m99","n":99,"ch":"c3","page":"c3","q":"Overfitting 的常見成因為何？","o":["訓練資料非常多","模型太簡單","訓練資料太少、特徵太多或模型太複雜","使用了 Dropout"],"a":2,"e":"增加訓練資料、降低模型複雜度是最簡單的避免方法。"},{"id":"m100","n":100,"ch":"c3","page":"c3","q":"何謂 Underfitting？","o":["只在測試集表現差","參數太多","連訓練資料都學不好","訓練太久"],"a":2,"e":"像連考古題都不會。"},{"id":"m101","n":101,"ch":"c3","page":"c3","q":"下列哪一種做法可以減少 Overfitting？","o":["大幅增加模型複雜度","減少訓練資料","拿 Test set 調整模型","增加訓練資料，或使用 Dropout、Data Augmentation"],"a":3,"e":"其他正則化方法還有 L1／L2、Early Stopping、Batch Normalization。"},{"id":"m102","n":102,"ch":"c3","page":"c3","q":"L1 正則化在 Loss Function 加上什麼？","o":["權重平方的總和","權重絕對值的總和","權重的最大值","梯度的總和"],"a":1,"e":"L1（Lasso）加 λΣ|w|。"},{"id":"m103","n":103,"ch":"c3","page":"c3","q":"L2 正則化在 Loss Function 加上什麼？","o":["權重平方的總和","權重絕對值的總和","bias 的總和","預測誤差"],"a":0,"e":"L2（Ridge）加 λΣw²。"},{"id":"m104","n":104,"ch":"c3","page":"c3","q":"哪一種正則化會把不重要特徵的權重降為 0？","o":["L2","BN","L1","Early Stopping"],"a":2,"e":"L1 對每個權重的推力一樣大，小權重很快被推到 0。"},{"id":"m105","n":105,"ch":"c3","page":"c3","q":"L2 正則化的效果為何？","o":["讓很多權重剛好變 0","讓所有權重一起變小，大的權重受到更大懲罰","讓權重變大","隨機關閉節點"],"a":1,"e":"L2 對大權重推得最用力。"},{"id":"m106","n":106,"ch":"c3","page":"c3","q":"正則化係數 λ 設得太大會造成什麼問題？","o":["Overfitting","Underfitting","梯度爆炸","參數變多"],"a":1,"e":"權重被壓得太小，學不到足夠的 pattern。"},{"id":"m107","n":107,"ch":"c3","page":"c3","q":"給定權重 (3, −0.1, 0)、λ=0.01，請計算 L1 penalty。","o":["0.031","0.0901","0.029","3.1"],"a":0,"e":"0.01 × (3 + 0.1 + 0) = 0.031；L2 則是 0.01 × 9.01 = 0.0901。"},{"id":"m108","n":108,"ch":"c3","page":"c3","q":"Dropout 是一種什麼樣的技術？","o":["資料擴增","優化器","正則化（防止 overfitting）","評估指標"],"a":2,"e":"模擬考第 3 題。"},{"id":"m109","n":109,"ch":"c3","page":"c3","q":"使用 Dropout 的模型在測試時如何運作？","o":["一樣隨機關閉一半節點","使用所有節點","只用被關閉過的節點","關閉所有節點"],"a":1,"e":"Dropout 只在訓練時作用。"},{"id":"m110","n":110,"ch":"c3","page":"c3","q":"Dropout 為什麼有助於提升模型表現？","o":["讓模型變大","模型不能依賴少數特定節點，被迫學到更可靠的特徵","增加訓練資料","讓學習率變大"],"a":1,"e":"每次訓練不同的子網路，效果類似集成（ensemble）。"},{"id":"m111","n":111,"ch":"c3","page":"c3","q":"Early Stopping 設定 patience=3，Val Loss 依序為 0.50、0.40、0.35、0.36、0.37、0.38，會在第幾個 epoch 停止？取回哪一個 epoch 的權重？","o":["第 4 停、取回第 4","第 6 停、取回第 6","第 3 停、取回第 3","第 6 停、取回第 3"],"a":3,"e":"第 3 個 epoch 最好，之後連續 3 個 epoch 沒進步就停，並取回最佳權重。"},{"id":"m112","n":112,"ch":"c3","page":"c3","q":"Early Stopping 停止後，應該使用哪一組權重？","o":["最後一個 epoch","驗證損失最低那一個 epoch","第一個 epoch","隨機一個"],"a":1,"e":"所以每個 epoch 都要存檔。"},{"id":"m113","n":113,"ch":"c3","page":"c3","q":"Batch Normalization 在推論時使用什麼統計量？","o":["當下 batch 的 mean 與 STD","固定為 0 與 1","訓練中用移動平均累積的 running_mean、running_STD","不做標準化"],"a":2,"e":"推論時 batch 可能只有一張，用當下統計量不合理。"},{"id":"m114","n":114,"ch":"c3","page":"c3","q":"Batch Normalization 的 γ 和 β 是什麼？","o":["人工設定的超參數","可學習的參數，負責縮放與平移","固定為 1 和 0","損失函數"],"a":1,"e":"y = γx̂ + β，經反向傳播更新。"},{"id":"m115","n":115,"ch":"c3","page":"c3","q":"Batch Normalization 通常放在哪裡？","o":["Conv 層與激活函數之間","輸出層之後","Softmax 之後","只放在輸入層"],"a":0,"e":"控制進入非線性函數前的數值分布。"},{"id":"m116","n":116,"ch":"c3","page":"c3","q":"Data Augmentation 通常用在哪一個資料集？","o":["測試資料","驗證資料","訓練資料","三份都要"],"a":2,"e":"在 Data Loader 取資料時即時產生。"},{"id":"m117","n":117,"ch":"c3","page":"c3","q":"MixUp 以 λ=0.7 混合狗圖與貓圖，新的標籤為何？","o":["狗 1、貓 0","狗 0.5、貓 0.5","狗 0.3、貓 0.7","狗 0.7、貓 0.3"],"a":3,"e":"圖片和標籤都以 7 : 3 混合。"},{"id":"m118","n":118,"ch":"c3","page":"c3","q":"CutMix 在 32×32 的 A 圖上貼一塊 16×16 的 B 圖，新的標籤為何？","o":["A 0.5、B 0.5","A 0.75、B 0.25","A 1、B 0","A 0.25、B 0.75"],"a":1,"e":"B 佔面積 256 ÷ 1,024 = 0.25。"},{"id":"m119","n":119,"ch":"c3","page":"c3","q":"CutOut 與 Random Erasing 的主要差異是什麼？","o":["CutOut 遮固定大小的正方形、填 0；Random Erasing 長寬比與面積隨機、填隨機值","兩者完全相同","CutOut 會混合兩張圖","Random Erasing 把四張圖拼成一張"],"a":0,"e":"兩者都屬於遮擋類擴增。"},{"id":"m120","n":120,"ch":"c3","page":"c3","q":"把 4 張圖片拼成一張的 Data Augmentation 方法是什麼？","o":["MixUp","GridMask","Mosaic","CutOut"],"a":2,"e":"屬於組合類，一張圖可看到不同背景、尺度、位置。"},{"id":"m121","n":121,"ch":"c4","page":"c4","q":"VGG16 的「16」代表什麼？","o":["16 層卷積","13 層卷積 ＋ 3 層全連接（有參數的層）","16 個濾波器","16 層 Pooling"],"a":1,"e":"Pooling 沒有參數，不算在內；VGG19 是 16 Conv ＋ 3 FC。"},{"id":"m122","n":122,"ch":"c4","page":"c4","q":"VGGNet 架構的主要特點為何？","o":["多種 kernel 並行再串接","殘差連接","全部用 3×3 卷積規整地堆疊，filter 數量逐段增加","Depthwise Separable Convolution"],"a":2,"e":"是「典型 CNN」的範本。"},{"id":"m123","n":123,"ch":"c4","page":"c4","q":"VGG16 約有 1.38 億個參數，大部分集中在哪裡？","o":["第一層卷積","Pooling 層","最後幾層卷積","全連接層"],"a":3,"e":"約 89% 在 FC 層。"},{"id":"m124","n":124,"ch":"c4","page":"c4","q":"VGGNet 的主要缺點為何？","o":["參數量龐大、計算需求大、參數冗餘","結構不規則","無法加深","只能處理灰階圖"],"a":0,"e":"優點是深度設計、結構規範、準確率高。"},{"id":"m125","n":125,"ch":"c4","page":"c4","q":"Inception Net 的設計動機為何？","o":["減少資料量","filter size 很難選，乾脆同一層並行多種大小讓網路自己學","解決梯度消失","讓模型放進手機"],"a":1,"e":"小 kernel 抓細節、大 kernel 抓大範圍，兩者都要。"},{"id":"m126","n":126,"ch":"c4","page":"c4","q":"Inception module 的做法為何？","o":["並行 1×1、3×3、5×5 卷積與 max pooling，再在通道方向串接","把輸入直接加到輸出","每層接收前面所有層的輸出","只用 1×1 卷積"],"a":0,"e":"(B) 是 ResNet，(C) 是 DenseNet。"},{"id":"m127","n":127,"ch":"c4","page":"c4","q":"為什麼 Inception module 的所有分支都要使用 same padding、stride=1？","o":["減少參數","增加非線性","讓各分支輸出的寬高相同，才能在通道方向串接","加快訓練"],"a":2,"e":"寬高不同就無法串接。"},{"id":"m128","n":128,"ch":"c4","page":"c4","q":"1×1 卷積的作用為何？","o":["縮小寬高","只在通道方向做加權組合，改變通道數但不改變寬高","取最大值","增加感受野"],"a":1,"e":"它不看鄰居，只混合、增減通道數。"},{"id":"m129","n":129,"ch":"c4","page":"c4","q":"Inception 在 3×3、5×5 卷積前先接 1×1 卷積（Bottleneck Layer）的主要目的為何？","o":["增加準確率","增加通道數","讓輸出變大","先壓低通道數，大幅降低運算量"],"a":3,"e":"先瘦身再做重工作。"},{"id":"m130","n":130,"ch":"c4","page":"c4","q":"28×28×192 輸出 32 個通道，直接用 5×5 卷積約需 120M 次乘法；先用 1×1 壓到 16 個通道再做 5×5，約需多少次乘法？","o":["約 12.4M（約 1/10）","約 60M","約 120M","約 240M"],"a":0,"e":"2.4M（1×1）＋ 10M（5×5）≈ 12.4M。"},{"id":"m131","n":131,"ch":"c4","page":"c4","q":"GoogLeNet 的 Auxiliary Classifier 在什麼時候使用？","o":["只在推論時使用","用來取代主分類器","只在訓練時使用，推論時移除","用來做資料擴增"],"a":2,"e":"讓前面的層也收得到訊號，幫助深層網路訓練。"},{"id":"m132","n":132,"ch":"c4","page":"c4","q":"Inception module 四個分支分別輸出 64、128、32、32 個通道，寬高都是 28×28，串接後的輸出大小為何？","o":["28×28×64","28×28×128","112×112×64","28×28×256"],"a":3,"e":"串接是通道數相加：64 ＋ 128 ＋ 32 ＋ 32 = 256。"},{"id":"m133","n":133,"ch":"c4","page":"c4","q":"ResNet 的殘差連接主要是為了解決什麼問題？","o":["資料太少造成的 overfitting","網路變深後連訓練誤差都上升的優化困難","模型放不進手機","需要多尺度特徵"],"a":1,"e":"講義強調深層網路變差「不是過擬合」。"},{"id":"m134","n":134,"ch":"c4","page":"c4","q":"ResNet 殘差區塊的輸出為何？","o":["H(x) = F(x) × x","H(x) = F(x) − x","H(x) = F(x) ＋ x","H(x) = [F(x), x]"],"a":2,"e":"把輸入 x 直接加到輸出；(D) 串接是 DenseNet。"},{"id":"m135","n":135,"ch":"c4","page":"c4","q":"為什麼 ResNet 讓網路學習恆等映射變得容易？","o":["只要讓殘差 F(x) → 0 就好","不需要訓練","參數比較多","用了 Softmax"],"a":0,"e":"堆疊的層只需學殘差 F(x) = H(x) − x。"},{"id":"m136","n":136,"ch":"c4","page":"c4","q":"ResNet 的捷徑用相加合併，因此有什麼要求？","o":["F(x) 和 x 的形狀必須相同","只要寬高相同","通道數必須不同","沒有任何要求"],"a":0,"e":"(B) 是串接（DenseNet、Inception）的要求。"},{"id":"m137","n":137,"ch":"c4","page":"c4","q":"殘差區塊反向傳播時 ∂H/∂x = ∂F/∂x ＋ 1，其中「＋1」的作用為何？","o":["增加參數","讓梯度至少有一條不會衰減的路，緩解梯度消失","讓輸出變大","防止 overfitting"],"a":1,"e":"梯度可以經由捷徑直接傳回前面的層。"},{"id":"m138","n":138,"ch":"c4","page":"c4","q":"20 層網路每層導數都是 0.5，傳到第一層的梯度約為 0.5²⁰ ≈ 9.5 × 10⁻⁷，這是什麼現象？","o":["梯度爆炸","過擬合","梯度消失","擬合不足"],"a":2,"e":"每層 1.5 則是 1.5²⁰ ≈ 3,325，梯度爆炸。"},{"id":"m139","n":139,"ch":"c4","page":"c4","q":"梯度消失與梯度爆炸的主要原因為何？","o":["資料太少","學習率太小","反向傳播時多層的導數連乘","用了 Pooling"],"a":2,"e":"導數小於 1 就指數消失，大於 1 就指數成長。"},{"id":"m140","n":140,"ch":"c4","page":"c4","q":"ResNet 的主要缺點為何？","o":["無法訓練深層網路","運算量與記憶體需求大，不利部署在行動裝置","準確率比 VGG 差","不能當 backbone"],"a":1,"e":"另外許多 block 學到的殘差很小，參數使用效率不佳。"},{"id":"m141","n":141,"ch":"c4","page":"c4","q":"7×7×512 的 Feature Map 經過 Global Average Pooling（GAP），輸出大小為何？","o":["1×1×512","7×7×1","25,088","1×1×1"],"a":0,"e":"每個通道取一個平均值。"},{"id":"m142","n":142,"ch":"c4","page":"c4","q":"Global Average Pooling 本身有幾個可學習參數？","o":["512","49","0","25,088"],"a":2,"e":"GAP 只是取平均。"},{"id":"m143","n":143,"ch":"c4","page":"c4","q":"GAP 之後得到 512 維向量，接到 1,000 類的 Fully Connected Layer，請計算參數量。","o":["512,000","513,000","25,089,000","1,512"],"a":1,"e":"(512 ＋ 1) × 1,000 = 513,000；若 Flatten（25,088 維）則是 25,089,000。"},{"id":"m144","n":144,"ch":"c4","page":"c4","q":"Global Average Pooling 的主要缺點為何？","o":["參數太多","容易 overfitting","輸入尺寸必須固定","丟失空間位置資訊，不適合直接做偵測、分割"],"a":3,"e":"另外小物體訊號可能被背景平均稀釋。"},{"id":"m145","n":145,"ch":"c4","page":"c4","q":"Global Average Pooling 的優點為何？","o":["保留特徵位置","對輸入尺寸更靈活，7×7 或 10×10 都輸出同樣長度","增加參數量","適合物件偵測"],"a":1,"e":"另外大幅減少參數、降低過擬合。"},{"id":"m146","n":146,"ch":"c4","page":"c4","q":"SqueezeNet 的設計目標為何？","o":["超越 ResNet 的準確率","維持 AlexNet 等級的準確率，參數量約為 AlexNet 的 1/50","讓模型更深","減少資料量"],"a":1,"e":"小模型方便傳輸、更新與部署。"},{"id":"m147","n":147,"ch":"c4","page":"c4","q":"SqueezeNet 的 Fire module 結構為何？","o":["squeeze（1×1）→ expand（1×1 與 3×3 並行）","3×3 → 5×5 → 7×7","depthwise → pointwise","卷積 → BN → 相加"],"a":0,"e":"先壓通道再展開；(C) 是 MobileNet。"},{"id":"m148","n":148,"ch":"c4","page":"c4","q":"關於 SqueezeNet 的敘述，何者正確？","o":["運算量一定比 AlexNet 少很多","準確率明顯高於 ResNet","參數少不代表運算少，延後下採樣讓運算量甚至高於 AlexNet","使用 Depthwise Separable Convolution"],"a":2,"e":"參數少 ≠ 運算少。"},{"id":"m149","n":149,"ch":"c4","page":"c4","q":"SqueezeNet 把部分 3×3 Filter 換成 1×1，每個 Filter 的參數會變成原本的多少？","o":["1/3","1/9","1/2","不變"],"a":1,"e":"1×1 ÷ 3×3 = 1/9。"},{"id":"m150","n":150,"ch":"c4","page":"c4","q":"MobileNet 的核心技術是什麼？","o":["殘差連接","Fire module","Depthwise Separable Convolution","輔助分類器"],"a":2,"e":"Depthwise ＋ Pointwise 兩步取代一般卷積。"},{"id":"m151","n":151,"ch":"c4","page":"c4","q":"何謂 Depthwise Convolution？","o":["每個輸入通道各自用一個 k×k×1 的 kernel，不混合通道","用 1×1 混合通道","所有通道一起卷積","取每個通道的平均"],"a":0,"e":"只看空間，通道各算各的。"},{"id":"m152","n":152,"ch":"c4","page":"c4","q":"Depthwise Separable Convolution 中的 Pointwise Convolution 是什麼？","o":["3×3 卷積","Max Pooling","1×1 卷積，負責混合通道","GAP"],"a":2,"e":"Depthwise 看空間、Pointwise 混通道。"},{"id":"m153","n":153,"ch":"c4","page":"c4","q":"使用 3×3 kernel、輸出通道很多時，Depthwise Separable Convolution 的運算量約為一般卷積的多少？","o":["約 1/2","約 1/9","約 1/100","一樣"],"a":1,"e":"比值 = 1/C_out ＋ 1/k² ≈ 1/9。"},{"id":"m154","n":154,"ch":"c4","page":"c4","q":"MobileNet 的 Width Multiplier α=0.5 時，運算量與參數量約變為原本的多少？","o":["0.25 倍","0.5 倍","2 倍","不變"],"a":0,"e":"輸入、輸出通道都乘 α，所以約 α² = 0.25。"},{"id":"m155","n":155,"ch":"c4","page":"c4","q":"MobileNet 的 Resolution Multiplier ρ 會影響什麼？","o":["只影響參數量","只影響運算量，參數量不變","兩者都不影響","只影響通道數"],"a":1,"e":"參數量公式裡沒有寬高。"},{"id":"m156","n":156,"ch":"c4","page":"c4","q":"要把模型部署在手機上，最需要參數少、運算量低，哪一個模型最適合？","o":["VGG16","ResNet-152","MobileNet","Inception"],"a":2,"e":"約 4.2M 參數，可用 α、ρ 再縮小。"},{"id":"m157","n":157,"ch":"c4","page":"c4","q":"關於模型的參數量、運算量與實際速度，何者正確？","o":["參數少的模型一定跑得快","運算量少的模型在 GPU 上一定等比例變快","參數少 ≠ 運算少 ≠ 實際速度快","參數量和輸入解析度成正比"],"a":2,"e":"SqueezeNet 參數少但運算不少；depthwise conv 在 GPU 上硬體利用率差。"},{"id":"m158","n":158,"ch":"c4","page":"c4","q":"給定輸入 12×12×3，使用 128 個 5×5 的 Filter，請計算卷積層的參數量（含 bias）。","o":["9,600","614,400","9,728","3,328"],"a":2,"e":"(5 × 5 × 3 ＋ 1) × 128 = 76 × 128 = 9,728。"},{"id":"m159","n":159,"ch":"c4","page":"c4-2","q":"DenseNet 如何合併前面各層的特徵？","o":["逐元素相加","通道串接（concatenation）","取最大值","取平均"],"a":1,"e":"ResNet 是相加，DenseNet 是串接。"},{"id":"m160","n":160,"ch":"c4","page":"c4-2","q":"DenseNet 的 growth rate k 代表什麼？","o":["每一層新增的特徵圖數量","學習率","層數","每層的輸入通道數"],"a":0,"e":"每層輸出固定為 k，越來越多的是輸入通道數。"},{"id":"m161","n":161,"ch":"c4","page":"c4-2","q":"Dense Block 的輸入通道 k₀=64、growth rate k=32，第 3 層的輸入通道數為何？","o":["96","128","160","32"],"a":1,"e":"64 ＋ 32 × (3 − 1) = 128。"},{"id":"m162","n":162,"ch":"c4","page":"c4-2","q":"Dense Block 的輸入通道 k₀=64、growth rate k=32，6 層的 Dense Block 輸出通道數為何？","o":["224","192","256","64"],"a":2,"e":"64 ＋ 6 × 32 = 256；224 是第 6 層的「輸入」。"},{"id":"m163","n":163,"ch":"c4","page":"c4-2","q":"為什麼 DenseNet 不在 Dense Block 內做降採樣？","o":["長寬改變就無法串接","會增加參數","會梯度爆炸","Pooling 不能用在 DenseNet"],"a":0,"e":"所以降採樣放在區塊之間的過渡層。"},{"id":"m164","n":164,"ch":"c4","page":"c4-2","q":"DenseNet 的 Transition Layer 由哪些部分組成？","o":["3×3 Conv ＋ Max Pooling","BN ＋ 1×1 Conv ＋ 2×2 Average Pooling","只有 GAP","FC ＋ Softmax"],"a":1,"e":"1×1 Conv 以 θ 壓縮通道，Average Pooling 讓長寬減半。"},{"id":"m165","n":165,"ch":"c4","page":"c4-2","q":"56×56×256 經過 Transition Layer（θ=0.5），輸出大小為何？","o":["56×56×128","28×28×256","28×28×128","14×14×64"],"a":2,"e":"通道 0.5 × 256 = 128，長寬 56 ÷ 2 = 28。"},{"id":"m166","n":166,"ch":"c4","page":"c4-2","q":"DenseNet 的主要缺點為何？","o":["參數比 ResNet 多很多","無法緩解梯度消失","記憶體需求高，實際速度不一定快","無法重用特徵"],"a":2,"e":"要保存同一區塊所有先前層的輸出，串接存取多。"},{"id":"m167","n":167,"ch":"c4","page":"c4-2","q":"DenseNet-BC 的 B 與 C 分別代表什麼？","o":["Batch Norm、Concatenation","Block、Classifier","Bottleneck、Concatenation","Bottleneck、Compression"],"a":3,"e":"B 是 1×1 瓶頸層，C 是過渡層用 θ &lt; 1 壓縮通道。"},{"id":"m168","n":168,"ch":"c4","page":"c4-2","q":"DenseNet-B 的 Bottleneck Layer 會先用 1×1 卷積把通道壓到多少？","o":["k","4k","2k","θk"],"a":1,"e":"先壓到 4k，再做 3×3 輸出 k 個。"},{"id":"m169","n":169,"ch":"c4","page":"c4-2","q":"為什麼 DenseNet 能用比 ResNet 少很多的參數達到相近的準確率？","o":["特徵重用，每層只需新增少量（k 個）特徵","用了更大的 kernel","沒有 BN","層數比較少"],"a":0,"e":"前面的特徵都保留下來，每層可以很窄。"},{"id":"m170","n":170,"ch":"c4","page":"c4-2","q":"DenseNet Composition Layer 的順序為何？","o":["Conv → BN → ReLU","ReLU → Conv → BN","BN → ReLU → 3×3 Conv","Conv → ReLU → Pool"],"a":2,"e":"先正規化與激活再卷積，稱為 pre-activation。"},{"id":"m171","n":171,"ch":"c5","page":"c5","q":"為什麼需要 Transfer Learning？","o":["預訓練模型比較便宜","新任務的類別一定和 ImageNet 相同","多數實際任務只有幾百到幾千張影像，難以從頭訓練","從頭訓練一定比較差"],"a":2,"e":"從頭訓練需要大量標註資料、強大運算資源與長時間。"},{"id":"m172","n":172,"ch":"c5","page":"c5","q":"Pretrained Model 的淺層通常學到什麼特徵？","o":["邊緣、色塊、紋理等通用特徵","原資料集特定類別的細節","類別機率","什麼都沒學到"],"a":0,"e":"深層才學到和原資料集相關的細節。"},{"id":"m173","n":173,"ch":"c5","page":"c5","q":"Feature Extraction 的做法為何？","o":["解凍全部層用大學習率訓練","只訓練卷積基底","從頭訓練整個模型","凍結卷積基底，換上新的分類層，只訓練新分類層"],"a":3,"e":"卷積基底的權重訓練時不更新。"},{"id":"m174","n":174,"ch":"c5","page":"c5","q":"Feature Extraction 時，新分類層的輸出數量應該等於多少？","o":["1,000","新資料集的類別數","卷積基底的通道數","batch size"],"a":1,"e":"原本對應 ImageNet 的分類層被移除。"},{"id":"m175","n":175,"ch":"c5","page":"c5","q":"Fine-tuning 時通常解凍哪些層？","o":["最淺的幾層","只有輸入層","較深（後面）的層","隨機挑選"],"a":2,"e":"淺層是通用特徵，深層才需要針對新資料調整。"},{"id":"m176","n":176,"ch":"c5","page":"c5","q":"Fine-tuning 時的 learning rate 通常如何設定？","o":["比初始訓練小一到兩個數量級","比初始訓練大 10 倍","和初始訓練一樣","設為 0"],"a":0,"e":"例如 0.01 → 0.001～0.0001，避免改壞預訓練權重。"},{"id":"m177","n":177,"ch":"c5","page":"c5","q":"Fine-tuning 時為什麼要先只訓練新的分類層，再解凍預訓練層？","o":["分類層參數最多","新分類層隨機初始化，一開始的大梯度會破壞預訓練權重","預訓練層不能算梯度","讓 BN 更新得更快"],"a":1,"e":"這是模擬考選填題的重點。"},{"id":"m178","n":178,"ch":"c5","page":"c5","q":"何謂凍結（Freeze）某些層？","o":["刪除這些層","把權重設為 0","用更大的學習率","訓練時不更新這些層的權重"],"a":3,"e":"這幾層上鎖。"},{"id":"m179","n":179,"ch":"c5","page":"c5","q":"Full Fine-tuning 的優點為何？","o":["適應能力最大，資料夠多時通常效果最好","記憶體需求最低","資料少時不會 overfitting","不需要訓練"],"a":0,"e":"domain 差異大時也比較有調整能力。"},{"id":"m180","n":180,"ch":"c5","page":"c5","q":"Full Fine-tuning 的缺點為何？","o":["適應能力太小","不能用 GPU","計算與記憶體需求高，資料少時容易 overfitting","無法更新分類層"],"a":2,"e":"所有參數都要存梯度與優化器狀態。"},{"id":"m181","n":181,"ch":"c5","page":"c5","q":"Last-k Fine-tuning 屬於哪一種微調方式？","o":["Full Fine-tuning","Partial／Selective Fine-tuning","PEFT","Regularized Fine-tuning"],"a":1,"e":"只解凍最後 k 個 layer／block。"},{"id":"m182","n":182,"ch":"c5","page":"c5","q":"Last-k Fine-tuning 的 k 是否包含新的分類 head？","o":["包含","只在 k = 1 時包含","視資料量而定","不包含，head 本來就一定要訓練"],"a":3,"e":"k 只算預訓練模型的 block。"},{"id":"m183","n":183,"ch":"c5","page":"c5","q":"新資料只有 500 張、和 ImageNet 很相似時，Last-k 的 k 應該如何選？","o":["小一點（1～2，甚至只做特徵提取）","越大越好","一定要 Full FT","和資料量無關"],"a":0,"e":"資料少 → k 小，避免 overfitting。"},{"id":"m184","n":184,"ch":"c5","page":"c5","q":"新資料和 ImageNet 差異很大、資料量又多時，Last-k 的 k 應該如何選？","o":["設為 0","小一點","大一點，甚至 Full FT","不能用遷移學習"],"a":2,"e":"差異大時淺層也可能需要重新適應。"},{"id":"m185","n":185,"ch":"c5","page":"c5","q":"Last-k 微調時，凍結的 block 裡有 BatchNorm，應該如何處理？","o":["只要把 requires_grad 設為 False","另外把凍結層的 BN 設為 eval 模式，沿用預訓練的統計量","刪掉 BN","用很大的學習率"],"a":1,"e":"running mean／std 不是靠梯度更新，只關 requires_grad 仍會被新資料改掉。"},{"id":"m186","n":186,"ch":"c5","page":"c5","q":"PEFT（Parameter-Efficient Fine-tuning）的核心概念為何？","o":["訓練全部參數","從頭訓練","只訓練分類層的 bias","凍結大部分預訓練模型，只訓練非常少量的參數"],"a":3,"e":"例如 LoRA、Adapter、VPT。"},{"id":"m187","n":187,"ch":"c5","page":"c5","q":"LoRA 屬於哪一種微調方式？","o":["Full Fine-tuning","Regularized Fine-tuning","Partial Fine-tuning","PEFT"],"a":3,"e":"PEFT 的方法還有 Adapter、VPT；L2-SP 才是 Regularized Fine-tuning。"},{"id":"m188","n":188,"ch":"c5","page":"c5","q":"PEFT 主要用在哪一類模型？","o":["ViT、CLIP 等大型 Transformer 模型","LeNet","KNN","PCA"],"a":0,"e":"講義寫主要用於 Vision Transformer、CLIP。"},{"id":"m189","n":189,"ch":"c5","page":"c5","q":"PEFT 在訓練時主要省下什麼？","o":["凍結參數的梯度與優化器狀態","各層的激活值","推論時所有的計算","訓練資料"],"a":0,"e":"反向傳播仍要經過每一層，各層激活值照樣要保存。"},{"id":"m190","n":190,"ch":"c5","page":"c5","q":"LoRA 的前向計算為何？","o":["h = W₀x ＋ b","h = BAx","h = (W₀ − BA)x","h = W₀x ＋ BAx"],"a":3,"e":"W₀ 凍結，只訓練低秩更新量 BA。"},{"id":"m191","n":191,"ch":"c5","page":"c5","q":"LoRA 訓練時會更新哪些參數？","o":["只有新增的小矩陣 B 與 A（加上新的分類 head）","只有 W₀","W₀、B、A 全部","只有 bias"],"a":0,"e":"預訓練權重 W₀ 凍結不更新。"},{"id":"m192","n":192,"ch":"c5","page":"c5","q":"給定一個 768×768 的線性層，加上 rank r=8 的 LoRA，請計算 LoRA 的參數量。","o":["589,824","6,144","12,288","4,718,592"],"a":2,"e":"r(d ＋ k) = 8 × (768 ＋ 768) = 12,288，約原本的 2%。"},{"id":"m193","n":193,"ch":"c5","page":"c5","q":"LoRA 初始化時，哪一個矩陣設為 0？","o":["A","B","W₀","都不設為 0"],"a":1,"e":"B = 0 讓一開始 BA = 0，模型和預訓練模型完全相同。"},{"id":"m194","n":194,"ch":"c5","page":"c5","q":"關於各種 PEFT 方法的推論成本，何者正確？","o":["LoRA 推論一定比較慢","Adapter 不增加推論成本","VPT 讓輸入序列變短","LoRA 可把 BA 合併回 W₀，推論不增加計算"],"a":3,"e":"Adapter 與 VPT 會增加推論計算量。"},{"id":"m195","n":195,"ch":"c5","page":"c5","q":"LoRA 的 rank r 選得太大會有什麼問題？","o":["失去省參數的優勢","學不夠","無法合併權重","模型無法訓練"],"a":0,"e":"r 太小可能學不夠；常見設定 4、8、16。"},{"id":"m196","n":196,"ch":"c5","page":"c5","q":"L2-SP 正則化會把權重拉向哪裡？","o":["0","隨機值","預訓練權重 w⁰","最大值"],"a":2,"e":"懲罰項 (α/2)‖w − w⁰‖²，SP 是 starting point。"},{"id":"m197","n":197,"ch":"c5","page":"c5","q":"一般的 weight decay（L2 正則化）會把權重拉向哪裡？","o":["預訓練權重","0","1","平均值"],"a":1,"e":"懲罰項 (α/2)‖w‖²。"},{"id":"m198","n":198,"ch":"c5","page":"c5","q":"為什麼使用 L2-SP 時不要再另外設定 weight_decay？","o":["會讓學習率變 0","會刪除分類層","程式會出錯","權重會同時被拉向 0 和 w⁰，互相拉扯"],"a":3,"e":"失去保留預訓練知識的目的。"},{"id":"m199","n":199,"ch":"c5","page":"c5","q":"關於 L2-SP 的敘述，何者正確？","o":["所有參數仍需訓練，不像 LoRA 減少可訓練參數","只訓練分類層","新分類 head 也拉向 w⁰","推論時要多算一次"],"a":0,"e":"新分類 head 沒有預訓練值，改用一般 L2。"},{"id":"m200","n":200,"ch":"c5","page":"c5","q":"ViT-Base（約 86M 參數）要服務 10 個任務：Full Fine-tuning 各存一份約 860M；LoRA 共用 backbone、每個任務約 0.59M，總共約需多少？","o":["860M","5.9M","約 92M","約 430M"],"a":2,"e":"86M ＋ 10 × 0.59M ≈ 91.9M，PEFT 多任務儲存很省。"},{"id":"m201","n":201,"ch":"c0","page":"c0","q":"Computer Vision 的目標為何？","o":["讓電腦能像人類一樣解釋和理解影像或影片中的視覺資訊","提高螢幕的解析度","壓縮影片檔案大小","設計新的相機硬體"],"a":0,"e":"CV 是結合電腦科學、ML、AI 的跨領域研究，目標是讓電腦「看懂」影像。"},{"id":"m202","n":202,"ch":"c0","page":"c0","q":"判斷整張圖屬於哪一個類別，屬於哪一種任務？","o":["Object Detection","Image Classification","Segmentation","Object Localization"],"a":1,"e":"Image Classification 只輸出一個類別標籤，回答「這是什麼？」。"},{"id":"m203","n":203,"ch":"c0","page":"c0","q":"找出圖中所有物體的位置與類別，屬於哪一種任務？","o":["Image Classification","Object Localization","Object Detection","Segmentation"],"a":2,"e":"Object Detection 輸出多個框與各自的類別，例如自駕車偵測行人。"},{"id":"m204","n":204,"ch":"c0","page":"c0","q":"以 pixel 為單位，標出每個像素屬於哪個類別的任務為何？","o":["Image Classification","Object Localization","Object Detection","Segmentation"],"a":3,"e":"Segmentation 是像素層級，用「描邊著色」取代「畫框」。"},{"id":"m205","n":205,"ch":"c0","page":"c0","q":"Object Localization 與 Object Detection 的主要差異是什麼？","o":["Localization 針對圖中單一（主要）物體，Detection 要找出所有物體","Localization 輸出像素層級的結果","Detection 不需要輸出類別","兩者完全相同"],"a":0,"e":"定位是「一個框」，偵測是「多個框」，兩者都要輸出類別。"},{"id":"m206","n":206,"ch":"c0","page":"c0","q":"電腦視覺四大任務中，輸出最細緻的是哪一個？","o":["Image Classification","Segmentation","Object Localization","Object Detection"],"a":1,"e":"細緻程度依序是分類（整張圖）→ 定位（一個框）→ 偵測（多個框）→ 分割（每個像素）。"},{"id":"m207","n":207,"ch":"c0","page":"c0","q":"Traditional CV 與 Modern CV 最根本的差異是什麼？","o":["Traditional CV 只能處理彩色圖片","Modern CV 不需要資料","特徵由人工設計，還是由模型從資料中自動學習","Traditional CV 一定比較準確"],"a":2,"e":"傳統 CV 由人工選擇特徵（例如蘋果「直徑 5～5.1 公分、紅色、圓形」），現代 CV 由深度學習模型自動學習特徵。"},{"id":"m208","n":208,"ch":"c0","page":"c0","q":"下列哪個情境最適合使用 Traditional CV？","o":["自駕車辨識行人","圖像生成","換臉（Deep Fakes）","工廠生產線瑕疵檢測"],"a":3,"e":"瑕疵的形狀、大小、顏色通常固定，可以寫出明確規則。"},{"id":"m209","n":209,"ch":"c0","page":"c0","q":"Traditional CV 的優點為何？","o":["快速、穩定、不需大量資料","能處理變化極大的情況","不需要人工設計特徵","規則越複雜越容易撰寫"],"a":0,"e":"規則明確、變化少的場景，傳統方法更快、更穩、更省成本。"},{"id":"m210","n":210,"ch":"c0","page":"c0","q":"為什麼自駕車辨識行人適合使用 Modern CV？","o":["行人外觀固定，容易寫規則","不需要任何訓練資料","行人的穿著、姿勢、光線、遮擋變化太多，人工規則寫不完","運算量比傳統方法少"],"a":2,"e":"看過大量道路圖片後，模型能自己學會行人的抽象特徵。"}],"short":[{"id":"s1","n":1,"ch":"c1","page":"c1","star":true,"q":"Machine Learning 與 Deep Learning 的主要差異是什麼？","a":"<p>最主要的差異在於<strong>特徵由誰決定</strong>：Machine Learning 由人工擷取特徵，Deep Learning 由模型自動學習特徵。</p>\n<ul>\n<li><strong>特徵</strong>：ML 是「輸入 → 人工擷取特徵 → 分類模型」；DL 由同一個神經網路同時做特徵擷取與分類</li>\n<li><strong>資料量</strong>：ML 較少資料就能訓練；DL 需要<strong>大量資料</strong></li>\n<li><strong>運算資源</strong>：ML 用 CPU 就能訓練；DL 通常需要 <strong>GPU</strong>、訓練較久</li>\n<li><strong>可解釋性</strong>：ML 較好；DL 較差，像黑盒子</li>\n<li>三者關係：AI ⊃ ML ⊃ DL</li>\n</ul>"},{"id":"s2","n":2,"ch":"c1","page":"c1","star":false,"q":"請簡述 Supervised Learning、Unsupervised Learning 與 Reinforcement Learning 各自的意義。","a":"<ul>\n<li><strong>Supervised Learning</strong>：輸入<strong>有標籤</strong>的資料，和正確答案比較算出誤差來修正；例如 SVM、KNN、影像分類</li>\n<li><strong>Unsupervised Learning</strong>：輸入<strong>沒有標籤</strong>的資料，自己找出資料的結構（分群、降維）；例如 PCA</li>\n<li><strong>Reinforcement Learning</strong>：不給正確答案，只依結果給<strong>獎勵（Reward）</strong>，學會讓長期獎勵最大的行動；例如遊戲、機器人控制</li>\n</ul>"},{"id":"s3","n":3,"ch":"c1","page":"c1","star":false,"q":"SVM 是一種什麼樣的方法？請簡述其原理，以及資料無法線性分割時如何處理。","a":"<p>SVM 是一種<strong>監督式學習的分類方法</strong>。</p>\n<ul>\n<li>原理：找一個<strong>最佳超平面（hyperplane）<strong>區分不同類別，同時</strong>最大化間隔（margin）</strong>，讓兩類資料離超平面越遠越好，加入新資料時才能維持高準確率</li>\n<li>無法線性分割時：使用 <strong>Kernel Trick</strong>，把資料投影到更高維的空間，讓原本線性不可分的資料變得可分</li>\n<li>缺點：大資料集計算耗時、kernel 難選、多分類較複雜</li>\n</ul>"},{"id":"s4","n":4,"ch":"c1","page":"c1","star":false,"q":"KNN 是如何進行分類的？請說明其步驟與主要缺點。","a":"<p>KNN 用<strong>距離</strong>判斷類別，看新樣本最近的 K 個鄰居多數屬於哪一類。</p>\n<ul>\n<li>步驟：① 計算新樣本與所有訓練樣本的距離 ② 取最近的 K 個鄰居 ③ <strong>多數決</strong>決定類別（K 通常設奇數，避免平手）</li>\n<li>缺點：① <strong>計算效率低</strong>，預測時要和所有樣本算距離 ② <strong>高維度資料表現不佳</strong>，距離失去意義 ③ 無法處理非線性關係</li>\n</ul>"},{"id":"s5","n":5,"ch":"c1","page":"c1","star":false,"q":"為什麼處理高維度資料時，Manhattan Distance 比 Euclidean Distance 穩健？","a":"<p>因為 Euclidean Distance 會把每一維的差<strong>平方</strong>，少數差異很大的維度會主導整個距離；Manhattan Distance 只取絕對值相加，<strong>每一維算得一樣重</strong>。</p>\n<ul>\n<li>例：A(0, 0)、B(10, 1)、C(7, 7)</li>\n<li>Euclidean：A→B ≈ 10.05、A→C ≈ 9.90，被 x 方向的 10 主導，兩者幾乎一樣遠</li>\n<li>Manhattan：A→B = 11、A→C = 14，反映出 C 兩個維度都有差異</li>\n</ul>"},{"id":"s6","n":6,"ch":"c1","page":"c1","star":false,"q":"PCA 的主要目的為何？請說明其原理與缺點。","a":"<p>PCA 的主要目的是<strong>降維</strong>：在保留資料主要資訊的同時，減少特徵數量。</p>\n<ul>\n<li>原理：把高維資料投影到<strong>變異性最大的方向</strong>（主成分，Principal Component）</li>\n<li>電腦視覺的用途：圖像降維、圖像去噪</li>\n<li>缺點：① 是<strong>線性方法</strong>，對非線性結構的資料處理有限 ② 只保留變異最大的方向，可能<strong>遺失細節</strong></li>\n</ul>"},{"id":"s7","n":7,"ch":"c1","page":"c1","star":true,"q":"為什麼神經網路需要 Activation Function？","a":"<p>Activation Function 的目的是<strong>引入非線性</strong>。</p>\n<ul>\n<li>每個節點只做 Σwx + b 是線性運算；沒有 Activation Function 時，<strong>疊再多層也只等於一層線性模型</strong>，學不出彎曲的決策邊界</li>\n<li>隱藏層常用 ReLU；輸出層二元分類用 Sigmoid、多類別分類用 Softmax</li>\n</ul>"},{"id":"s8","n":8,"ch":"c1","page":"c1","star":true,"q":"ReLU 是一種什麼樣的 Activation Function？請說明其優點與缺點。","a":"<p>ReLU（Rectified Linear Unit）定義為 <strong>max(0, x)</strong>：負數轉為 0、正數保留。</p>\n<ul>\n<li>優點：只要比大小，<strong>計算快</strong>；正值區梯度固定為 1，<strong>不會像 Sigmoid 一樣梯度消失</strong></li>\n<li>缺點：<strong>Dying ReLU</strong>，神經元持續輸出負值時梯度為 0，永久停止學習</li>\n<li>改善：使用 <strong>Leaky ReLU</strong>（負數區保留 0.1 的斜率）或 <strong>ELU</strong></li>\n</ul>"},{"id":"s9","n":9,"ch":"c1","page":"c1","star":false,"q":"Sigmoid 與 Softmax 的主要差異是什麼？","a":"<p>兩者都把輸出層的分數轉成機率，差別在用途：</p>\n<ul>\n<li><strong>Sigmoid</strong>：用於<strong>二元分類</strong>，輸出一個 0～1 的數，代表「是正類」的機率</li>\n<li><strong>Softmax</strong>：用於<strong>多類別分類</strong>，把每個類別的分數轉成<strong>加總為 1</strong> 的機率分布；例如 (2.4, 0, −1.5) → (0.90, 0.08, 0.02)</li>\n</ul>"},{"id":"s10","n":10,"ch":"c1","page":"c1","star":false,"q":"分類任務與迴歸任務各使用什麼 Loss Function？","a":"<ul>\n<li><strong>分類任務</strong>：<strong>Cross-Entropy</strong>，模型給正確答案的機率越低，損失越大</li>\n<li><strong>迴歸任務</strong>：<strong>MSE</strong>（均方誤差）或 <strong>MAE</strong>（平均絕對誤差）</li>\n<li>MSE 有平方，大誤差罰得特別重</li>\n<li>MAE 對離群值比較不敏感</li>\n</ul>"},{"id":"s11","n":11,"ch":"c1","page":"c1","star":false,"q":"請簡述 Forward Propagation 與 Backward Propagation 各自扮演的角色。","a":"<ul>\n<li><strong>Forward Propagation</strong>：資料從輸入層一層一層算到輸出層（每個節點先算 z = Σwx + b，再套 Activation Function），得到預測值，再用 Loss Function 算出誤差</li>\n<li><strong>Backward Propagation</strong>：把誤差往回傳，用<strong>連鎖律（Chain Rule）<strong>算出 Loss 對每個權重的</strong>梯度</strong>，再交給梯度下降更新權重</li>\n<li>兩者反覆進行，直到 Loss 最小化</li>\n</ul>"},{"id":"s12","n":12,"ch":"c1","page":"c1","star":true,"q":"Learning Rate 扮演什麼角色？太大或太小會發生什麼問題？","a":"<p>Learning Rate 決定<strong>每次梯度下降時權重更新多少</strong>（w_new = w_old − α × 梯度），是需要調整的<strong>超參數</strong>。</p>\n<ul>\n<li><strong>太大</strong>：更新太快，可能<strong>跳過最佳解</strong>、來回震盪，甚至發散</li>\n<li><strong>太小</strong>：更新太慢，要很久才收斂，可能到不了最佳解</li>\n</ul>"},{"id":"s13","n":13,"ch":"c1","page":"c1","star":true,"q":"請解釋 Batch Gradient Descent、SGD 與 Mini-batch Gradient Descent 的區別。","a":"<p>三者的差別在於<strong>每次更新權重時看多少筆資料</strong>：</p>\n<ul>\n<li><strong>Batch Gradient Descent</strong>：每次用<strong>全部</strong>訓練資料（一次看全部），路徑穩定，但慢、記憶體需求大</li>\n<li><strong>SGD</strong>：每次只用<strong>一筆</strong>資料（一次看一張），更新快，但波動大、收斂不穩；波動<strong>可能幫助跳出 local minima</strong></li>\n<li><strong>Mini-batch Gradient Descent</strong>：每次用<strong>一小批</strong>（例如 32、64 張），介於兩者之間，能利用 GPU 平行運算，<strong>實務最常用</strong></li>\n</ul>"},{"id":"s14","n":14,"ch":"c1","page":"c1","star":false,"q":"Adam Optimizer 是一種什麼樣的方法？","a":"<p>Adam 是結合 <strong>Momentum</strong> 與 <strong>RMSProp</strong> 的優化器，同時調整更新的方向與步伐。</p>\n<ul>\n<li><strong>Momentum</strong>：參考上一步的移動（慣性），決定<strong>方向</strong>；在平坦處或局部最小值仍能前進</li>\n<li><strong>RMSProp</strong>：依最近平方梯度的平均調整每個參數的學習率，決定<strong>步伐大小</strong>；梯度大就走小步、梯度小就走大步</li>\n<li>常用的預設值 β₁ = 0.9、β₂ = 0.999</li>\n</ul>"},{"id":"s15","n":15,"ch":"c1","page":"c1","star":false,"q":"Label Encoding 與 One-Hot Encoding 的主要差異是什麼？","a":"<ul>\n<li><strong>Label Encoding</strong>：每個類別給一個數字（Apple = 1、Chicken = 2、Broccoli = 3），會產生<strong>虛假順序</strong>，模型可能誤以為類別之間有大小關係</li>\n<li><strong>One-Hot Encoding</strong>：每個類別一個 0／1 欄位，沒有順序問題，但類別越多欄位越多，造成<strong>維度爆炸</strong></li>\n</ul>"},{"id":"s16","n":16,"ch":"c2","page":"c2","star":true,"q":"（模擬考第 1 題）為什麼需要使用 Padding？","a":"<p>Padding 是在輸入圖片外圍補 0，目的有兩個：</p>\n<ol>\n<li><strong>避免 feature map 越卷越小</strong>：沒有 padding 時每卷一次就縮小（5×5 卷 3×3 → 3×3），模型深時很快縮到太小；補一圈 0（5×5 → 7×7）後輸出可維持 5×5</li>\n<li><strong>增加邊緣、角落像素的貢獻</strong>：沒有 padding 時角落像素只被卷積一次，中間像素被卷積很多次，邊緣資訊容易被忽略</li>\n</ol>"},{"id":"s17","n":17,"ch":"c2","page":"c2","star":true,"q":"（模擬考第 2 題）Pooling 的主要目的為何？","a":"<p>Pooling 的主要目的是<strong>縮小 feature map 的尺寸，在不丟失重要資訊的情況下減少後續的計算量與訓練參數</strong>。</p>\n<ul>\n<li>原因：相鄰像素通常有相似的特徵，用一個值（例如 Max Pooling 取最大值）代表一個區塊即可</li>\n<li>同時讓模型<strong>不受微小特徵差異（例如些微位移）影響</strong></li>\n<li>常用 2×2、stride 2 → 高寬減半、深度不變；Pooling 沒有可訓練參數；stride 太大會丟失重要資訊</li>\n</ul>"},{"id":"s18","n":18,"ch":"c2","page":"c2","star":true,"q":"（模擬考第 4 題）給定輸入影像大小為 28×28，使用 5×5 的 Filter，stride=1，padding=0，請計算輸出 Feature Map 的大小。","a":"<ul>\n<li>公式：m = (n + 2p − f) / s + 1</li>\n<li>代入：(28 + 2 × 0 − 5) / 1 + 1 = <strong>24</strong></li>\n<li>答：輸出 Feature Map 為 <strong>24×24</strong>（1 個 Filter 是 24×24×1；N_f 個 Filter 深度就是 N_f）</li>\n</ul>"},{"id":"s19","n":19,"ch":"c2","page":"c2","star":true,"q":"（模擬考第 6 題）請解釋何謂「參數（parameter）」與「超參數（hyperparameter）」的區別。","a":"<ul>\n<li><strong>參數</strong>：<strong>訓練過程中由模型自己學習</strong>的變數，例如卷積層 Filter 的權重與 bias、Fully Connected Layer 的權重與 bias；由<strong>梯度下降與反向傳播</strong>更新</li>\n<li><strong>超參數</strong>：<strong>訓練前由人手動設定</strong>、模型不會自己學的值，例如 Filter 大小、Filter 數量、stride、padding、節點數、Activation Function、learning rate、batch size、epoch 數、Dropout rate；通常看 <strong>Validation</strong> 結果調整</li>\n<li>ReLU、Max Pooling、Flatten 層沒有可訓練參數</li>\n</ul>"},{"id":"s20","n":20,"ch":"c2","page":"c2","star":true,"q":"（模擬考第 8 題）在 CNN 的架構中，Fully Connected Layer 扮演什麼角色？","a":"<p>Fully Connected Layer（又稱 Dense Layer）負責<strong>整合前面卷積層與池化層抽出的特徵，並據此完成分類</strong>。</p>\n<ul>\n<li>進入 FC 前先把多維 feature map **展平（Flatten）**成一維向量</li>\n<li>每個節點都和下一層每個節點相連，把各處的局部特徵組合起來做整體判斷</li>\n<li><strong>最後一層的節點數等於類別數</strong>，接 <strong>Softmax</strong> 輸出各類別機率</li>\n<li>FC 通常是 CNN 中<strong>參數最多</strong>的部分（講義 MNIST 例子約 98%）</li>\n</ul>"},{"id":"s21","n":21,"ch":"c2","page":"c2","star":true,"q":"（模擬考第 10 題）為什麼在處理圖像任務時，CNN 通常比一般的全連接神經網路更有效？請說明兩項 CNN 的優勢。","a":"<ol>\n<li><strong>參數共享（Parameter Sharing）</strong>：同一個 Filter 的參數在整張圖不同位置重複使用，參數量和輸入圖片大小無關</li>\n<li><strong>連接稀疏性（Sparsity of Connections）</strong>：每個輸出只由輸入的一小塊（例如 3×3）算出來；28×28 灰階圖用全連接層產生 21,632 個節點要 784 × 21,632 = 16,959,488 個參數，CNN 的 Conv_1 只要 (3 × 3 × 1 + 1) × 32 = 320 個 → 訓練快、較不容易 overfitting</li>\n<li><strong>不變性（Invariance）</strong>：特徵不論出現在圖片哪個位置都能被偵測到</li>\n</ol>\n<p>另外，CNN 直接在二維上卷積，<strong>保留像素的空間結構</strong>，並自動學習邊緣、紋理等特徵。</p>"},{"id":"s22","n":22,"ch":"c2","page":"c2","star":false,"q":"請解釋何謂 Convolution、Filter 與 Feature Map。","a":"<ul>\n<li><strong>Convolution</strong>：Filter 在輸入圖上滑動，每個位置把對應元素相乘後相加（再加 bias），得到一個值</li>\n<li><strong>Filter（Kernel）</strong>：卷積用的小權重矩陣，是可學習的參數，相當於<strong>特徵偵測器</strong>（例如垂直邊緣偵測器）</li>\n<li><strong>Feature Map</strong>：卷積的輸出矩陣，標出「哪裡有這個特徵」；用幾個 Filter 就有幾張 Feature Map</li>\n</ul>"},{"id":"s23","n":23,"ch":"c2","page":"c2","star":false,"q":"給定輸入 [[1, 2, 0], [0, 1, 3], [2, 1, 0]]，使用 Filter [[1, 0], [0, −1]]，stride=1，padding=0，請計算輸出 Feature Map。","a":"<ul>\n<li>輸出大小：3 − 2 + 1 = 2 → 2×2</li>\n<li>左上 [[1, 2], [0, 1]]：1 × 1 + 2 × 0 + 0 × 0 + 1 × (−1) = <strong>0</strong></li>\n<li>右上 [[2, 0], [1, 3]]：2 − 3 = <strong>−1</strong></li>\n<li>左下 [[0, 1], [2, 1]]：0 − 1 = <strong>−1</strong></li>\n<li>右下 [[1, 3], [1, 0]]：1 − 0 = <strong>1</strong></li>\n<li>答：<strong>[[0, −1], [−1, 1]]</strong></li>\n</ul>"},{"id":"s24","n":24,"ch":"c2","page":"c2","star":false,"q":"Stride 扮演什麼角色？使用不同的 stride 有什麼好處？","a":"<p>Stride 是 <strong>Filter 每次移動的格數</strong>；stride 越大，輸出 Feature Map 越小。</p>\n<ul>\n<li>好處：增加模型訓練效率、減少重複使用相同的像素、控制 Feature Map 的大小</li>\n<li>例：5×5 輸入、3×3 Filter，stride=1 → 3×3；stride=2 → 2×2</li>\n</ul>"},{"id":"s25","n":25,"ch":"c2","page":"c2","star":false,"q":"給定輸入 32×32×3，使用 10 個 5×5 的 Filter，stride=1，padding=0，請計算輸出 Feature Map 的大小。","a":"<ul>\n<li>邊長：(32 + 0 − 5) / 1 + 1 = 28</li>\n<li>深度 = Filter 數量 = 10</li>\n<li>答：<strong>28×28×10</strong></li>\n</ul>"},{"id":"s26","n":26,"ch":"c2","page":"c2","star":false,"q":"給定輸入 28×28×1，使用 32 個 3×3 的 Filter，請計算卷積層的參數量。","a":"<ul>\n<li>公式：(f × f × 輸入深度 + 1) × Filter 數量</li>\n<li>每個 Filter：3 × 3 × 1 = 9 個權重 ＋ 1 個 bias = 10</li>\n<li>答：10 × 32 = <strong>320</strong></li>\n</ul>"},{"id":"s27","n":27,"ch":"c2","page":"c2","star":false,"q":"Max Pooling 與 Average Pooling 的主要差異是什麼？","a":"<ul>\n<li><strong>Max Pooling</strong>：每個區塊取<strong>最大值</strong>，保留最強的特徵，最常用</li>\n<li><strong>Average Pooling</strong>：每個區塊取<strong>平均值</strong>，結果較平滑，保留整體資訊</li>\n<li>兩者都沒有可訓練參數，也都不改變深度</li>\n</ul>"},{"id":"s28","n":28,"ch":"c2","page":"c2","star":false,"q":"給定 4×4 輸入 [[4, 123, 1, 34], [56, 99, 222, 253], [45, 122, 165, 12], [21, 187, 133, 124]]，使用 2×2、stride=2 的 Max Pooling，請計算輸出。","a":"<ul>\n<li>左上 max(4, 123, 56, 99) = 123</li>\n<li>右上 max(1, 34, 222, 253) = 253</li>\n<li>左下 max(45, 122, 21, 187) = 187</li>\n<li>右下 max(165, 12, 133, 124) = 165</li>\n<li>答：<strong>[[123, 253], [187, 165]]</strong></li>\n</ul>"},{"id":"s29","n":29,"ch":"c2","page":"c2","star":true,"q":"卷積什麼時候使用小的 Filter，什麼時候使用大的 Filter？","a":"<ul>\n<li><strong>小的 Filter（3×3）</strong>：感受野小，擅長抓<strong>細節</strong>（邊緣、紋理），參數與運算少，大部分的層都用</li>\n<li><strong>大的 Filter（5×5、7×7）</strong>：感受野大，擅長抓<strong>大範圍</strong>的形狀，但參數與運算多</li>\n<li>實務上多用<strong>多層 3×3 取代大的 Filter</strong>；不確定要選哪個時，可以像 Inception 一樣同時使用多種大小</li>\n</ul>"},{"id":"s30","n":30,"ch":"c2","page":"c2","star":false,"q":"為什麼常用兩層 3×3 卷積取代一層 5×5 卷積？","a":"<ul>\n<li><strong>感受野相同</strong>：兩層 3×3 疊起來看得到 5×5 的範圍</li>\n<li><strong>參數較少</strong>：每對輸入／輸出通道 2 × 9 = 18 個權重，5×5 要 25 個</li>\n<li><strong>多一次非線性</strong>：每層後面都接 ReLU，表達能力更強</li>\n<li>這就是 VGGNet 全部使用 3×3 的原因</li>\n</ul>"},{"id":"s31","n":31,"ch":"c2","page":"c2","star":false,"q":"CNN 中哪些層沒有可訓練的參數？為什麼？","a":"<p><strong>ReLU、Max Pooling、Flatten</strong> 沒有可訓練的參數，因為它們都是固定的運算：</p>\n<ul>\n<li>ReLU：固定的 max(0, x)</li>\n<li>Max Pooling：固定取最大值</li>\n<li>Flatten：只是把多維排成一維</li>\n</ul>\n<p>有參數的是卷積層（Filter 權重 ＋ bias）和 Fully Connected Layer。</p>"},{"id":"s32","n":32,"ch":"c2","page":"c2","star":false,"q":"請解釋 Filter 的深度與 Filter 的數量的區別。","a":"<ul>\n<li><strong>Filter 的深度</strong>必須<strong>等於輸入的頻道數</strong>：RGB 輸入時，3×3 的 Filter 其實是 3×3×3</li>\n<li><strong>Filter 的數量</strong>決定<strong>輸出 Feature Map 的深度</strong>：用 16 個 Filter，輸出深度就是 16</li>\n</ul>"},{"id":"s33","n":33,"ch":"c2","page":"c2","star":false,"q":"請簡述卷積層、Pooling 層與 Fully Connected Layer 各自扮演的角色。","a":"<ul>\n<li><strong>卷積層</strong>：用 Filter <strong>抽取特徵</strong>（邊緣、紋理…），有可訓練參數，輸出深度 = Filter 數量</li>\n<li><strong>Pooling 層</strong>：<strong>縮小 Feature Map、減少計算量</strong>，沒有參數，深度不變</li>\n<li><strong>Fully Connected Layer</strong>：<strong>整合特徵、完成分類</strong>，參數通常最多，最後一層節點數 = 類別數</li>\n</ul>"},{"id":"s34","n":34,"ch":"c2","page":"c2","star":false,"q":"給定輸入 64×64×3，使用 16 個 3×3 的 Filter，stride=1，padding=1，請計算輸出 Feature Map 的大小。","a":"<ul>\n<li>邊長：(64 + 2 × 1 − 3) / 1 + 1 = 64</li>\n<li>深度 = Filter 數量 = 16</li>\n<li>答：<strong>64×64×16</strong>（3×3 搭配 padding=1，尺寸不變）</li>\n</ul>"},{"id":"s35","n":35,"ch":"c2","page":"c2","star":false,"q":"給定輸入 7×7，使用 3×3 的 Filter，stride=2，padding=1，請計算輸出 Feature Map 的大小。","a":"<ul>\n<li>公式：⌊(n + 2p − f) / s⌋ + 1</li>\n<li>代入：⌊(7 + 2 − 3) / 2⌋ + 1 = 3 + 1 = <strong>4</strong></li>\n<li>答：<strong>4×4</strong></li>\n</ul>"},{"id":"s36","n":36,"ch":"c3","page":"c3","star":true,"q":"（模擬考第 9 題）在訓練機器學習模型時，Training、Validation 和 Test 資料集各自扮演什麼角色？","a":"<ul>\n<li><strong>Training set</strong>：讓模型<strong>學習參數</strong>，每個 epoch 用梯度下降與反向傳播更新權重</li>\n<li><strong>Validation set</strong>：<strong>訓練期間</strong>對模型做公正評估（每個 epoch 結束算 loss 與 accuracy），用來<strong>調整超參數、挑選最佳模型、判斷是否 overfitting 或 Early Stopping</strong>；不用來更新權重</li>\n<li><strong>Test set</strong>：模型<strong>從未看過</strong>的資料，<strong>訓練全部結束後只用一次</strong>，評估最終的泛化能力</li>\n<li>注意：Test 不能拿來調模型，否則評估結果會過度樂觀</li>\n</ul>"},{"id":"s37","n":37,"ch":"c3","page":"c3","star":true,"q":"（模擬考第 7 題）請簡述 Precision、Recall 與 Accuracy 三個指標各自代表的意義。","a":"<ul>\n<li><strong>Accuracy</strong>：所有樣本中預測正確的比例，(TP + TN) / (TP + TN + FP + FN)</li>\n<li><strong>Precision</strong>：<strong>被預測為正</strong>的樣本中，真的是正的比例，TP / (TP + FP)（預測為陽性的可信度）</li>\n<li><strong>Recall</strong>（＝ Sensitivity、TPR）：<strong>實際為正</strong>的樣本中，被正確找出的比例，TP / (TP + FN)（有沒有漏抓）</li>\n<li>類別不平衡時 Accuracy 可能很高但模型其實不好，要搭配 Precision 與 Recall</li>\n</ul>"},{"id":"s38","n":38,"ch":"c3","page":"c3","star":true,"q":"（模擬考第 3 題）Dropout 是一種什麼樣的技術？請簡述其運作原理以及它為什麼有助於提升模型表現。","a":"<p>Dropout 是一種<strong>正則化（Regularization）技術</strong>，用來防止過度擬合。</p>\n<ul>\n<li>運作原理：\n  1. 訓練時，每個 mini-batch 隨機關閉某一層的部分節點（比例由 Dropout Rate 控制）\n  2. 前向與反向傳遞只經過開著的節點，也只更新這些節點的權重\n  3. 下一個 mini-batch 恢復所有節點，再重新隨機關閉一批\n  4. <strong>測試時不關閉，使用所有節點</strong></li>\n<li>為什麼有效：每次訓練的都是不同的子網路，模型<strong>不能依賴少數特定節點</strong>，被迫學到更可靠的特徵，泛化較好</li>\n<li>代價：收斂較慢，需要更多 epoch</li>\n</ul>"},{"id":"s39","n":39,"ch":"c3","page":"c3","star":true,"q":"（模擬考第 5 題）L1 與 L2 正則化的主要差異是什麼？","a":"<p>兩者都在 Loss Function 加上 Penalty，迫使模型使用較小的權重，強度由 λ 控制：</p>\n<ul>\n<li><strong>L1（Lasso）</strong>：加權重<strong>絕對值</strong>總和 λΣ|w|；優先把不重要特徵的權重<strong>降為 0</strong>，有<strong>特徵選取</strong>的效果</li>\n<li><strong>L2（Ridge）</strong>：加權重<strong>平方</strong>總和 λΣw²；把<strong>所有權重一起變小</strong>，大的權重受到更大懲罰</li>\n<li>λ 太大會讓權重被壓得過小，造成 <strong>Underfitting</strong></li>\n</ul>"},{"id":"s40","n":40,"ch":"c3","page":"c3","star":false,"q":"Confusion Matrix 扮演什麼角色？為什麼只看 Accuracy 不夠？","a":"<p>Confusion Matrix 以「真實類別 × 預測類別」統計預測結果，可以看出<strong>哪一類表現較差、被誤認成什麼</strong>。</p>\n<ul>\n<li>對角線是預測正確，其他格是預測錯誤；例如 MNIST 的 4 容易被預測成 9</li>\n<li>Accuracy 只給整體答對比例，回答不了「是不是傾向把 8 判成 3」這種問題</li>\n<li>類別不平衡時更明顯：100 人只有 5 人有病，全部猜沒病也有 95% Accuracy，但 Recall = 0</li>\n</ul>"},{"id":"s41","n":41,"ch":"c3","page":"c3","star":false,"q":"給定 TP=45、FN=5、FP=15、TN=35，請計算 Accuracy、Precision 與 Recall。","a":"<ul>\n<li>Accuracy = (45 + 35) / 100 = <strong>0.8</strong></li>\n<li>Precision = 45 / (45 + 15) = <strong>0.75</strong></li>\n<li>Recall = 45 / (45 + 5) = <strong>0.9</strong></li>\n</ul>"},{"id":"s42","n":42,"ch":"c3","page":"c3","star":true,"q":"何謂 Overfitting？如何避免？","a":"<p>Overfitting 是指模型在<strong>訓練資料上表現很好，但在沒看過的資料上表現很差</strong>（泛化能力差）。</p>\n<ul>\n<li>常見成因：訓練資料太少、特徵太多、模型太複雜</li>\n<li>避免方法：</li>\n<li>增加訓練資料（含 Data Augmentation）、降低模型複雜度</li>\n<li>正則化：<strong>L1／L2、Dropout、Early Stopping、Batch Normalization</strong></li>\n</ul>"},{"id":"s43","n":43,"ch":"c3","page":"c3","star":false,"q":"Early Stopping 是一種什麼樣的技術？請簡述其運作原理。","a":"<p>Early Stopping 是一種<strong>正則化技術</strong>，在模型開始 overfitting 之前停止訓練。</p>\n<ul>\n<li>每個 epoch 都計算 Validation loss 並儲存模型權重</li>\n<li>設定門檻 patience P：如果接下來 <strong>P 個 epoch 都沒有更好的結果就停止訓練</strong></li>\n<li>停止後<strong>取回驗證損失最低那一個 epoch 的權重</strong>，不是最後一個</li>\n</ul>"},{"id":"s44","n":44,"ch":"c3","page":"c3","star":false,"q":"Batch Normalization 的主要目的為何？訓練與推論時有什麼不同？","a":"<p>Batch Normalization 的主要目的是<strong>穩定每一層輸入的分布</strong>，讓訓練更穩定。</p>\n<ul>\n<li>做法：對每個 mini-batch 計算 mean 與 STD 做標準化，再用可學習的 **γ（縮放）、β（平移）**調整；通常放在卷積層與 Activation Function 之間</li>\n<li><strong>訓練時</strong>：使用當下 mini-batch 的 mean 與 STD</li>\n<li><strong>推論時</strong>：改用訓練中以移動平均累積的 <strong>running_mean、running_STD</strong>（推論時 batch 可能只有一張）</li>\n</ul>"},{"id":"s45","n":45,"ch":"c3","page":"c3","star":false,"q":"為什麼 Precision 與 Recall 通常需要取捨？醫療篩檢應該重視哪一個？","a":"<p>提升其中一個，另一個通常就會下降（tradeoff）：門檻調低會抓到更多正例（Recall 上升），但誤報也變多（Precision 下降）。</p>\n<ul>\n<li>醫療篩檢應該重視 <strong>Recall</strong>：寧可多抽幾個人去複檢，也不要漏掉真的病人</li>\n<li>兩者都要顧時看 <strong>F1</strong>（Precision 與 Recall 的調和平均）</li>\n</ul>"},{"id":"s46","n":46,"ch":"c3","page":"c3","star":false,"q":"Data Augmentation 的主要目的為何？","a":"<p>Data Augmentation 的主要目的是<strong>增加訓練資料的多樣性，減少 Overfitting</strong>（Overfitting 的原因之一是訓練資料不夠）。</p>\n<ul>\n<li>基本方法：翻轉、旋轉、縮放、裁切、亮度與對比、扭曲</li>\n<li><strong>只對訓練資料</strong>做，通常在 Data Loader 取資料時即時產生</li>\n<li>進階方法：遮擋類（CutOut、Random Erasing、Hide-and-Seek、GridMask）、混合類（MixUp、CutMix）、組合類（Copy-Paste、Mosaic）</li>\n</ul>"},{"id":"s47","n":47,"ch":"c3","page":"c3","star":false,"q":"MixUp 與 CutMix 的主要差異是什麼？","a":"<ul>\n<li><strong>MixUp</strong>：兩張圖<strong>整張</strong>按比例疊合，標籤也按同樣比例混合（例如 λ = 0.7 → 狗 0.7、貓 0.3）</li>\n<li><strong>CutMix</strong>：在 A 圖挖一塊換成 B 圖（<strong>局部替換</strong>），標籤<strong>依面積比例</strong>混合（32×32 貼 16×16 → A 0.75、B 0.25）</li>\n</ul>"},{"id":"s48","n":48,"ch":"c3","page":"c3","star":false,"q":"為什麼 L1 正則化會把權重推到 0，而 L2 不會？","a":"<ul>\n<li><strong>L1</strong> 的懲罰 λ|w| 斜率固定是 λ，<strong>不管權重大小都推一樣大力</strong>，小權重很快就被推到 0</li>\n<li><strong>L2</strong> 的懲罰 λw² 斜率是 2λw，<strong>權重越小推力越小</strong>，越接近 0 越推不動，所以只會變小、很少剛好變 0；大權重則被推得最用力</li>\n</ul>"},{"id":"s49","n":49,"ch":"c4","page":"c4","star":true,"q":"VGGNet 的主要特點為何？為什麼全部使用 3×3 卷積？","a":"<p>VGGNet 是「典型 CNN」的範本：<strong>多層 3×3 卷積後接 Pooling，Filter 數量逐段增加，最後接 Fully Connected Layer</strong>（VGG16 = 13 Conv ＋ 3 FC）。</p>\n<ul>\n<li>全部用 3×3 的原因：兩層 3×3 的感受野等於 5×5，但<strong>參數較少</strong>（18 對 25），且每層後面都有 ReLU，<strong>多了非線性</strong></li>\n<li>優點：深度設計、結構規範、準確率高</li>\n<li>缺點：<strong>參數龐大</strong>（約 1.38 億，大多在 FC）、計算需求大、參數冗餘</li>\n</ul>"},{"id":"s50","n":50,"ch":"c4","page":"c4","star":true,"q":"Inception Net 的設計動機為何？請簡述 Inception module 的結構。","a":"<ul>\n<li>設計動機：設計 CNN 時 <strong>Filter size 最難選</strong>，小 kernel 擅長抓細節、大 kernel 擅長抓大範圍的特徵；Inception 選擇<strong>不必選，在同一層並行使用多種 Filter，讓網路自己學</strong></li>\n<li>Inception module：</li>\n<li>並行使用 <strong>1×1、3×3、5×5 卷積與 max pooling</strong></li>\n<li>所有分支用 same padding、stride=1，輸出寬高相同，再在<strong>通道方向串接</strong></li>\n<li>用 <strong>1×1 卷積當 Bottleneck Layer</strong> 降低運算量</li>\n</ul>"},{"id":"s51","n":51,"ch":"c4","page":"c4","star":false,"q":"1×1 卷積扮演什麼角色？","a":"<p>1×1 卷積在每個像素位置把所有通道加權相加，<strong>改變通道數但不改變寬高</strong>。</p>\n<ul>\n<li>當 <strong>Bottleneck Layer</strong>：在 3×3、5×5 卷積前先壓少通道，降低運算量（Inception、DenseNet-B）</li>\n<li>接在 Pooling 後調整通道數（Pooling 不改變通道數）</li>\n<li>是 Depthwise Separable Convolution 的 <strong>Pointwise</strong> 那一步，負責混合通道</li>\n</ul>"},{"id":"s52","n":52,"ch":"c4","page":"c4","star":false,"q":"Inception 中的 Bottleneck Layer 的主要目的為何？","a":"<p>主要目的是<strong>降低運算量</strong>：在昂貴的 3×3、5×5 卷積前，先用 1×1 卷積把通道數壓少。</p>\n<ul>\n<li>例：28×28×192 輸出 32 個通道</li>\n<li>直接 5×5：約 <strong>120M</strong> 次乘法</li>\n<li>先 1×1 壓到 16 通道（約 2.4M）再做 5×5（約 10M）：約 <strong>12.4M</strong>，約原本的 <strong>1/10</strong></li>\n<li>只要壓縮比例合理，對準確率影響不大</li>\n</ul>"},{"id":"s53","n":53,"ch":"c4","page":"c4","star":false,"q":"GoogLeNet 的 Auxiliary Classifier 扮演什麼角色？","a":"<p>Auxiliary Classifier 是接在網路中間的分類器，<strong>讓前面的層也收得到梯度訊號，幫助深層網路訓練</strong>。</p>\n<ul>\n<li>總損失：Total Loss = Main Loss ＋ w₁ × Aux Loss1 ＋ w₂ × Aux Loss2</li>\n<li><strong>只在訓練時使用，推論時移除</strong></li>\n</ul>"},{"id":"s54","n":54,"ch":"c4","page":"c4","star":true,"q":"ResNet 主要解決什麼問題？為什麼說這不是 Overfitting？","a":"<p>ResNet 解決的是<strong>網路很深時效能反而下降、難以優化</strong>的問題（例如 50 層比 20 層還差），原因之一是梯度消失／爆炸。</p>\n<ul>\n<li>不是 Overfitting：深層網路變差時<strong>連訓練誤差也變差</strong>；Overfitting 是訓練表現好、測試表現差</li>\n<li>解法：<strong>殘差連接（skip connection）</strong>，把前面的輸入直接加到後面的輸出</li>\n</ul>"},{"id":"s55","n":55,"ch":"c4","page":"c4","star":false,"q":"ResNet 的殘差學習 H(x) = F(x) ＋ x 為什麼比較容易訓練？","a":"<ul>\n<li>堆疊的層只需學<strong>殘差 F(x) = H(x) − x</strong>，不用從頭學整個 H(x)；要達到恆等映射只要 F(x) → 0，容易很多</li>\n<li>講義比喻：傳統網路每次從空白紙重畫，ResNet 先給原圖，只改需要改的地方</li>\n<li>反向傳播時 ∂H/∂x = ∂F/∂x ＋ <strong>1</strong>，那個 +1 讓梯度至少有一條不會衰減的路，緩解梯度消失</li>\n</ul>"},{"id":"s56","n":56,"ch":"c4","page":"c4","star":true,"q":"何謂梯度消失與梯度爆炸？如何改善？","a":"<p>反向傳播時要把多層的導數<strong>連乘</strong>：</p>\n<ul>\n<li><strong>梯度消失</strong>：導數小於 1，連乘後趨近 0（每層 0.5，20 層後 ≈ 9.5 × 10⁻⁷），前面的層幾乎不更新</li>\n<li><strong>梯度爆炸</strong>：導數大於 1，連乘後變得很大（每層 1.5，20 層後 ≈ 3,325），更新一次跳太遠</li>\n<li>改善方法：使用 <strong>ReLU</strong>、<strong>Batch Normalization</strong>、<strong>殘差連接</strong>（ResNet）、DenseNet 的密集連接</li>\n</ul>"},{"id":"s57","n":57,"ch":"c4","page":"c4","star":true,"q":"Global Average Pooling 的主要目的為何？有什麼優缺點？","a":"<p>GAP 把每張 Feature Map 取一個平均值（例如 7×7×512 → 1×1×512），主要目的是<strong>取代 Flatten ＋ 大型 Fully Connected Layer，大幅減少參數</strong>。</p>\n<ul>\n<li>優點：① GAP 本身<strong>沒有參數</strong> ② 降低 overfitting ③ <strong>對輸入尺寸更靈活</strong></li>\n<li>缺點：① <strong>丟失空間位置資訊</strong>，不適合直接做物件偵測、語意分割 ② 小物體的訊號可能被背景稀釋</li>\n</ul>"},{"id":"s58","n":58,"ch":"c4","page":"c4","star":false,"q":"給定 7×7×512 的 Feature Map，接到 1,000 類的輸出，請比較 Flatten＋FC 與 GAP＋FC 的參數量。","a":"<ul>\n<li>Flatten：7 × 7 × 512 = 25,088 維；(25,088 + 1) × 1,000 = <strong>25,089,000</strong></li>\n<li>GAP：512 維（GAP 本身 0 參數）；(512 + 1) × 1,000 = <strong>513,000</strong></li>\n<li>GAP 少了約 49 倍（就是 7×7）</li>\n</ul>"},{"id":"s59","n":59,"ch":"c4","page":"c4","star":true,"q":"SqueezeNet 的設計目標為何？請簡述其三個設計策略。","a":"<p>設計目標：<strong>維持 AlexNet 等級的準確率，參數量約為 AlexNet 的 1/50</strong>，方便傳輸、更新與部署。</p>\n<ol>\n<li>把部分 <strong>3×3 Filter 換成 1×1</strong>（參數變 1/9）</li>\n<li><strong>減少輸入到 3×3 Filter 的通道數</strong></li>\n<li><strong>延後下採樣</strong>，在較大的 Feature Map 上運算以維持準確率</li>\n</ol>\n<p>策略一、二由 Fire module 實現。</p>"},{"id":"s60","n":60,"ch":"c4","page":"c4","star":false,"q":"SqueezeNet 的 Fire module 是什麼樣的結構？","a":"<p>Fire module 由 <strong>squeeze layer → expand layer</strong> 組成：</p>\n<ul>\n<li><strong>squeeze layer</strong>：只有 1×1 Filter，先把通道數壓少</li>\n<li><strong>expand layer</strong>：1×1 與 3×3 Filter 並行，再把輸出串接</li>\n<li>squeeze 的 Filter 數遠小於 expand（約 1/8），先壓縮再展開，所以 3×3 的輸入通道少、參數少</li>\n</ul>"},{"id":"s61","n":61,"ch":"c4","page":"c4","star":true,"q":"MobileNet 的 Depthwise Separable Convolution 是一種什麼樣的技術？","a":"<p>Depthwise Separable Convolution 把一般卷積<strong>拆成兩步</strong>，大幅降低運算量：</p>\n<ol>\n<li><strong>Depthwise Convolution</strong>：每個輸入通道各自用一個 k×k×1 的 kernel，只看空間、不混通道</li>\n<li><strong>Pointwise Convolution</strong>：用 1×1 卷積把通道做線性組合，決定輸出通道數</li>\n</ol>\n<ul>\n<li>運算量約為一般卷積的 1/C_out ＋ 1/k²，3×3 時約省 8～9 倍</li>\n<li>目的：讓 CNN 能在手機、嵌入式裝置上即時執行</li>\n</ul>"},{"id":"s62","n":62,"ch":"c4","page":"c4","star":false,"q":"MobileNet 的 Width Multiplier α 與 Resolution Multiplier ρ 各影響什麼？","a":"<ul>\n<li><strong>α</strong>：每層輸入、輸出通道數都乘 α，<strong>運算量與參數量</strong>都約變 <strong>α²</strong> 倍（α = 0.5 → 約 1/4）</li>\n<li><strong>ρ</strong>：縮小輸入解析度，<strong>運算量</strong>約變 <strong>ρ²</strong> 倍，<strong>參數量不變</strong></li>\n</ul>"},{"id":"s63","n":63,"ch":"c4","page":"c4","star":false,"q":"為什麼說「參數少」不等於「運算少」，也不等於「實際速度快」？","a":"<p>參數量只和 kernel 大小、通道數有關；運算量還和 Feature Map 的寬高有關；實際速度又受硬體與記憶體存取影響。</p>\n<ul>\n<li><strong>SqueezeNet</strong>：參數約 AlexNet 的 1/50，但延後下採樣讓運算量甚至更高</li>\n<li><strong>MobileNet</strong>：運算量低，但 depthwise conv 在 GPU 上硬體利用率差，不一定等比例變快</li>\n<li><strong>DenseNet</strong>：參數與 FLOPs 少，但大量串接與記憶體存取讓實際速度不一定快</li>\n</ul>"},{"id":"s64","n":64,"ch":"c4","page":"c4","star":true,"q":"請簡述 VGGNet、Inception、ResNet、DenseNet、SqueezeNet、MobileNet 各自的特點。","a":"<table>\n<thead>\n<tr>\n<th>模型</th>\n<th>特點</th>\n<th>優點</th>\n<th>缺點</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>VGGNet</td>\n<td>全部 3×3 規整堆疊</td>\n<td>結構規範、準確率高</td>\n<td>參數龐大、計算大</td>\n</tr>\n<tr>\n<td>Inception</td>\n<td>多種 kernel 並行再串接 ＋ 1×1 瓶頸</td>\n<td>多尺度特徵、運算高效</td>\n<td>結構複雜、難移植</td>\n</tr>\n<tr>\n<td>ResNet</td>\n<td>殘差連接 H(x) = F(x) ＋ x</td>\n<td>可訓練極深網路、常用 backbone</td>\n<td>運算與記憶體大</td>\n</tr>\n<tr>\n<td>DenseNet</td>\n<td>每層和前面所有層串接</td>\n<td>特徵重用、參數少</td>\n<td>記憶體需求高</td>\n</tr>\n<tr>\n<td>SqueezeNet</td>\n<td>Fire module</td>\n<td>參數是 AlexNet 的 1/50</td>\n<td>準確率只有 AlexNet 級</td>\n</tr>\n<tr>\n<td>MobileNet</td>\n<td>Depthwise Separable Convolution</td>\n<td>運算量低、適合手機</td>\n<td>準確率低於 ResNet</td>\n</tr>\n</tbody>\n</table>"},{"id":"s65","n":65,"ch":"c4","page":"c4","star":true,"q":"DenseNet 與 ResNet 的主要差異是什麼？","a":"<p>最主要的差異是<strong>合併特徵的方式</strong>：</p>\n<ul>\n<li><strong>ResNet</strong>：y = F(x) ＋ x，<strong>逐元素相加</strong>；輸入輸出形狀必須相同，舊特徵和新特徵混在一起</li>\n<li><strong>DenseNet</strong>：y = [x₀, x₁, …]，<strong>通道串接</strong>；只要長寬相同，前面的特徵完整保留，後面每一層都能直接取用</li>\n<li>結果：DenseNet <strong>特徵重用</strong>、每層可以很窄，參數比 ResNet 少；但要保存所有先前層的輸出，<strong>記憶體需求高</strong></li>\n</ul>"},{"id":"s66","n":66,"ch":"c4","page":"c4-2","star":false,"q":"DenseNet 的 growth rate k 扮演什麼角色？","a":"<p>growth rate k 是<strong>每一層新增的 Feature Map 數量</strong>，控制模型的大小。</p>\n<ul>\n<li>每層輸出固定是 k，越來越多的是<strong>輸入</strong>通道數：第 L 層輸入 k₀ ＋ k(L − 1)</li>\n<li>例：k₀ = 64、k = 32，6 層的 Dense Block 輸出 64 ＋ 6 × 32 = 256</li>\n</ul>"},{"id":"s67","n":67,"ch":"c4","page":"c4-2","star":false,"q":"給定 Dense Block 的輸入通道數為 32、growth rate k=16、共 4 層，請計算 Dense Block 的輸出通道數。","a":"<ul>\n<li>公式：k₀ ＋ k × L</li>\n<li>代入：32 ＋ 16 × 4 = <strong>96</strong></li>\n</ul>"},{"id":"s68","n":68,"ch":"c4","page":"c4-2","star":false,"q":"DenseNet 的 Transition Layer 扮演什麼角色？DenseNet-BC 代表什麼？","a":"<ul>\n<li><strong>Transition Layer</strong>：Dense Block 內長寬不能變（才能串接），所以<strong>降採樣放在區塊之間</strong>；由 BN ＋ 1×1 Conv（以壓縮因子 θ 減少通道）＋ 2×2 Average Pooling（長寬減半）組成</li>\n<li><strong>DenseNet-BC</strong>：同時使用 <strong>B</strong>ottleneck（3×3 前先用 1×1 壓到 4k）與 <strong>C</strong>ompression（θ &lt; 1）</li>\n</ul>"},{"id":"s69","n":69,"ch":"c5","page":"c5","star":false,"q":"何謂 Transfer Learning？為什麼需要它？","a":"<p>Transfer Learning 是<strong>利用在其他領域（例如 ImageNet）訓練好的 Pretrained Model，以較少的資料和較短的訓練時間，在新任務上取得好的表現</strong>。</p>\n<ul>\n<li>原因：從頭訓練 CNN 需要大量標註資料、強大運算資源與長時間，多數實際任務只有幾百到幾千張影像</li>\n<li>Pretrained Model 的淺層學到的邊緣、色塊、紋理等<strong>通用特徵</strong>也適用於新任務</li>\n</ul>"},{"id":"s70","n":70,"ch":"c5","page":"c5","star":false,"q":"Feature Extraction 與 Fine-tuning 的主要差異是什麼？","a":"<ul>\n<li><strong>Feature Extraction</strong>：<strong>凍結</strong>卷積基底，移除原本的分類層、換成新的分類層（輸出數 = 新類別數），<strong>只訓練新的分類層</strong></li>\n<li><strong>Fine-tuning</strong>：完成 Feature Extraction 後，再<strong>解凍部分或全部</strong>預訓練層（通常是較深的層），用<strong>很小的 learning rate</strong> 再訓練幾個 epoch</li>\n</ul>"},{"id":"s71","n":71,"ch":"c5","page":"c5","star":true,"q":"（模擬考選填題）我不太懂微調時為什麼要先凍結預訓練模型，只訓練新的分類層，再解凍後面的幾層。如果一開始就把整個模型一起訓練，不是可以更快適應新的資料嗎？","a":"<p>因為新的分類層是<strong>隨機初始化</strong>的：一開始預測幾乎是亂猜，Loss 很大，反向傳播回去的<strong>梯度也很大</strong>；如果這時整個模型一起訓練，大梯度會流進預訓練層，<strong>把在 ImageNet 學好的特徵破壞掉</strong>。</p>\n<ul>\n<li>兩階段：① 先凍結、只訓練新的分類層，讓 Loss 降下來、梯度穩定 ② 再解凍後面幾層，用很小的 learning rate 輕輕調整</li>\n<li>一開始全部一起訓練不一定比較快：大梯度打亂預訓練權重，等於部分從頭學起；新資料通常很少，也容易 overfitting</li>\n</ul>"},{"id":"s72","n":72,"ch":"c5","page":"c5","star":false,"q":"Fine-tuning 時為什麼通常解凍後面的層，並使用很小的 learning rate？","a":"<ul>\n<li><strong>解凍後面的層</strong>：淺層學到邊緣、色塊、紋理等<strong>通用特徵</strong>，換任務也用得上；深層才是和原資料集相關的細節，需要針對新資料調整</li>\n<li><strong>很小的 learning rate</strong>：通常比初始訓練<strong>小一到兩個數量級</strong>，避免一下子把預訓練好的權重改壞，只做小幅調整</li>\n</ul>"},{"id":"s73","n":73,"ch":"c5","page":"c5","star":false,"q":"請簡述 CV 中常見的四種微調方式。","a":"<ul>\n<li><strong>Full Fine-tuning</strong>：所有參數都微調；適應能力最大，但計算與記憶體成本高，資料少時容易 overfitting</li>\n<li><strong>Partial／Selective Fine-tuning</strong>：只更新部分參數，例如 <strong>Last-k</strong>（只解凍最後 k 個 block）</li>\n<li><strong>PEFT</strong>：凍結大部分模型，只訓練極少量參數，例如 <strong>LoRA</strong></li>\n<li><strong>Regularized Fine-tuning</strong>：參數可以動，但不要離預訓練值太遠，例如 <strong>L2-SP</strong></li>\n</ul>"},{"id":"s74","n":74,"ch":"c5","page":"c5","star":false,"q":"Last-k Fine-tuning 的 k 應該如何選擇？","a":"<ul>\n<li>新資料<strong>少</strong> → k <strong>小</strong>（1～2）；資料多 → k 大</li>\n<li>新資料和來源資料<strong>差異小</strong> → k <strong>小</strong>；差異<strong>大</strong> → k <strong>大</strong></li>\n<li>k 不包含新的分類 head（head 一定要訓練）</li>\n</ul>"},{"id":"s75","n":75,"ch":"c5","page":"c5","star":false,"q":"PEFT 是一種什麼樣的方法？有什麼優缺點？","a":"<p>PEFT（Parameter-Efficient Fine-tuning）<strong>凍結大部分 Pretrained Model，只訓練非常少量的參數</strong>，例如 LoRA、Adapter、VPT，主要用於 ViT、CLIP 等大型 Transformer。</p>\n<ul>\n<li>優點：可訓練參數很少、GPU 記憶體較省、<strong>多任務儲存很省</strong>（共用一個 backbone）</li>\n<li>缺點：適應能力可能受限；Adapter、VPT 會增加推論成本</li>\n</ul>"},{"id":"s76","n":76,"ch":"c5","page":"c5","star":false,"q":"LoRA 是一種什麼樣的技術？請簡述其原理。","a":"<p>LoRA（Low-Rank Adaptation）是一種 PEFT 方法：<strong>凍結預訓練權重，只訓練少量的低秩矩陣</strong>。</p>\n<ul>\n<li>原理：h = W₀x ＋ <strong>BA</strong>x；W₀ 凍結不更新，只訓練小矩陣 B（d × r）與 A（r × k），r 遠小於 d、k</li>\n<li>參數量只有 r(d ＋ k)，例如 768×768、r = 8 只要 12,288 個（約 2%）</li>\n<li>訓練完可以把 BA 加回 W₀，推論時不增加計算量</li>\n</ul>"},{"id":"s77","n":77,"ch":"c5","page":"c5","star":false,"q":"給定一個 512×512 的線性層，使用 rank r=4 的 LoRA，請計算需要訓練的參數量。","a":"<ul>\n<li>公式：r × (d ＋ k)</li>\n<li>代入：4 × (512 ＋ 512) = <strong>4,096</strong></li>\n<li>原本 512 × 512 = 262,144，LoRA 只要約 1.56%</li>\n</ul>"},{"id":"s78","n":78,"ch":"c5","page":"c5","star":false,"q":"L2-SP 與一般的 weight decay 的主要差異是什麼？","a":"<p>差別在於<strong>把權重拉向哪裡</strong>：</p>\n<ul>\n<li><strong>Weight decay</strong>：懲罰 (α/2)‖w‖²，把權重<strong>拉向 0</strong></li>\n<li><strong>L2-SP</strong>：懲罰 (α/2)‖w − w⁰‖²，把權重<strong>拉向預訓練值 w⁰</strong>（SP = starting point），保留預訓練學到的知識</li>\n<li>兩者不要同時使用，否則權重會同時被拉向 0 和 w⁰</li>\n</ul>"},{"id":"s79","n":79,"ch":"c5","page":"c5","star":false,"q":"為什麼 Fine-tuning 時，凍結層的 BatchNorm 要沿用預訓練的統計量？","a":"<p>因為新資料量小時，小 batch 估出來的 mean、STD 很不穩定，會<strong>打亂原本學到的特徵</strong>。</p>\n<ul>\n<li>預訓練的 running mean／std 是在大量資料上估出來的，比較穩定</li>\n<li>做法：把凍結層的 BN <strong>設為 eval 模式</strong>；只把 requires_grad 關掉不夠，統計量仍會被新資料更新</li>\n</ul>"},{"id":"s80","n":80,"ch":"c5","page":"c5","star":false,"q":"Regularized Fine-tuning 的核心概念為何？","a":"<p>核心概念是：<strong>可以讓參數動，但不要讓它們離 Pretrained Model 太遠</strong>。</p>\n<ul>\n<li>常見做法：<strong>L2-SP</strong>，在 Loss 加上 (α/2)‖w − w⁰‖²</li>\n<li>優點：降低 overfitting、保留預訓練知識、可以搭配 Full 或部分微調</li>\n<li>缺點：來源與目標差太多時可能反而有害；所有參數仍需訓練，成本沒有 PEFT 低</li>\n</ul>"},{"id":"s81","n":81,"ch":"c0","page":"c0","star":false,"q":"何謂 Computer Vision？請簡述其目標。","a":"<p>Computer Vision 是讓電腦能像人類一樣<strong>解釋和理解數位影像或影片中的視覺資訊</strong>的研究。</p>\n<ul>\n<li><strong>跨領域</strong>：結合電腦科學、<strong>Machine Learning</strong>、<strong>Artificial Intelligence</strong></li>\n<li><strong>應用</strong>：車牌辨識、自駕車、臉部辨識、人體姿態辨識、圖像生成等</li>\n</ul>"},{"id":"s82","n":82,"ch":"c0","page":"c0","star":false,"q":"請簡述電腦視覺四大任務（Image Classification、Object Localization、Object Detection、Segmentation）各自的意義。","a":"<p>四大任務的差別在於<strong>輸出的細緻程度</strong>，由粗到細依序是分類、定位、偵測、分割。</p>\n<ul>\n<li><strong>Image Classification</strong>：判斷整張圖屬於哪一個類別，輸出一個標籤</li>\n<li><strong>Object Localization</strong>：找出圖中（主要）物體的位置（一個框）並分類</li>\n<li><strong>Object Detection</strong>：找出圖中<strong>所有</strong>物體的位置與類別（多個框）</li>\n<li><strong>Segmentation</strong>：以 <strong>pixel</strong> 為單位，標出每個像素屬於哪個類別或物體</li>\n</ul>"},{"id":"s83","n":83,"ch":"c0","page":"c0","star":false,"q":"Traditional CV 與 Modern CV 的主要差異是什麼？","a":"<p>最主要的差異在於<strong>特徵由誰決定</strong>：Traditional CV 由人工手動選擇特徵，Modern CV 由模型（深度學習）從大量資料中自動學習特徵。</p>\n<ul>\n<li><strong>Traditional CV</strong>：工程師自己寫規則，例如蘋果是「直徑 5～5.1 公分、紅色、圓形」；<strong>快速、穩定、不需大量資料</strong>，但情況複雜時規則寫不完</li>\n<li><strong>Modern CV</strong>：把大量圖片丟給模型，讓它自己學出「蘋果長什麼樣子」；能處理<strong>變化極大</strong>的情況，但<strong>需要大量資料</strong></li>\n</ul>"},{"id":"s84","n":84,"ch":"c0","page":"c0","star":false,"q":"為什麼工廠瑕疵檢測適合使用 Traditional CV，而自駕車辨識行人適合使用 Modern CV？","a":"<p>關鍵在於<strong>能不能用明確規則描述目標</strong>：能 → 傳統方法；變化太多寫不完 → 現代方法。</p>\n<ul>\n<li><strong>瑕疵檢測</strong>：瑕疵的形狀、大小、顏色通常固定，可以寫出明確規則（例如「長度超過 2mm 的刮痕」），傳統方法快速、穩定、<strong>更具成本效益</strong>；用現代方法是「殺雞用牛刀」</li>\n<li><strong>行人辨識</strong>：行人的穿著、姿勢、高矮、膚色各不相同，加上天氣、光線、<strong>遮擋</strong>，人工規則寫不完；現代方法看過大量道路圖片後，能自己學會行人的<strong>抽象特徵</strong></li>\n</ul>"},{"id":"s85","n":85,"ch":"c4","page":"c4","star":false,"q":"使用 Global Average Pooling (GAP) 取代傳統接在 flatten 後面的大型 FC 層，對「參數量」與「過擬合風險」有什麼好處？","a":"<p>GAP 把每張 Feature Map 取一個平均值，<strong>本身沒有參數</strong>，所以能<strong>大幅減少參數量</strong>；參數變少，模型比較難死記訓練資料，<strong>降低 overfitting 風險</strong>。</p>\n<ul>\n<li><strong>參數量</strong>：以 7×7×512 接 1,000 類為例，Flatten ＋ FC 是 (25,088 + 1) × 1,000 = <strong>25,089,000</strong>；GAP ＋ FC 是 (512 + 1) × 1,000 = <strong>513,000</strong>，約少 <strong>49 倍</strong>（就是 7×7）</li>\n<li><strong>過擬合風險</strong>：大型 FC 層是 CNN 參數最多、最容易 overfitting 的地方；換成 GAP 後可學習的參數少很多，泛化能力較好</li>\n<li>代價：丟失空間位置資訊</li>\n</ul>"}]};
